1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4	import { v2RealtimeClient } from "@/lib/v2/supabase-browser";
5	import type { RealtimeChannel } from "@supabase/supabase-js";
6	import { compressImage, compressVideo, extractVideoFrame } from "@/lib/v2/gallery-compress";
7	import { extractExifDate, extractVideoDate } from "@/lib/v2/gallery-exif";
8	import MediaViewer, { type ViewerItem, type ViewerUser } from "./MediaViewer";
9	import { useNameMode } from "./NameMode";
10	import { pickName, type NameMode } from "@/lib/v2/profile";
11	import styles from "./photos.module.css";
12	/* eslint-disable @next/next/no-img-element */
13	
14	interface UploaderRef {
15	  display_name: string;
16	  first_name?: string | null;
17	  last_name?: string | null;
18	  avatar_url: string | null;
19	}
20	
21	interface Item {
22	  id: string;
23	  uploader_id: string;
24	  media_url: string;
25	  thumbnail_url: string | null;
26	  media_type: "photo" | "video";
27	  caption: string | null;
28	  width: number | null;
29	  height: number | null;
30	  taken_at: string | null;
31	  created_at: string;
32	  bulk_id: string | null;
33	  uploader: UploaderRef | UploaderRef[] | null;
34	  reactions: { emoji: string; user_id: string }[] | null;
35	  tags: { tagged_user_id: string }[] | null;
36	  comments: { count: number }[] | null;
37	}
38	type Sort = "taken" | "uploaded";
39	
40	const one = <T,>(v: T | T[] | null | undefined): T | null => (Array.isArray(v) ? v[0] ?? null : v ?? null);
41	
42	/** Transform a raw gallery row into the shape MediaViewer consumes. */
43	function toViewerItem(it: Item, userId: string, mode: NameMode): ViewerItem {
44	  const reactions: Record<string, { count: number; hasReacted: boolean }> = {};
45	  for (const r of it.reactions || []) {
46	    const e = reactions[r.emoji] || { count: 0, hasReacted: false };
47	    e.count += 1;
48	    if (r.user_id === userId) e.hasReacted = true;
49	    reactions[r.emoji] = e;
50	  }
51	  const up = one(it.uploader);
52	  return {
53	    id: it.id,
54	    media_url: it.media_url,
55	    thumbnail_url: it.thumbnail_url,
56	    media_type: it.media_type,
57	    caption: it.caption,
58	    width: it.width,
59	    height: it.height,
60	    created_at: it.created_at,
61	    taken_at: it.taken_at,
62	    uploader_id: it.uploader_id,
63	    uploader: { display_name: pickName(up, mode), avatar_url: up?.avatar_url ?? null },
64	    reactions,
65	    reactionCount: Object.values(reactions).reduce((s, r) => s + r.count, 0),
66	    tags: (it.tags || []).map((t) => t.tagged_user_id),
67	    commentCount: it.comments?.[0]?.count ?? 0,
68	  };
69	}
70	
71	/**
72	 * Photo gallery grid. Mirrors the legacy filters: sort toggle (Date Taken /
73	 * Date Uploaded), a year select, and a tagged-Loozer multi-select. Lazy
74	 * thumbnails, infinite scroll, realtime new items.
75	 */
76	export default function PhotosDrawer({
77	  orgId,
78	  userId,
79	  isAdmin,
80	  initialPhotoId,
81	  initialBulkId,
82	}: {
83	  orgId: string;
84	  userId: string;
85	  isAdmin: boolean;
86	  initialPhotoId?: string;
87	  initialBulkId?: string;
88	}) {
89	  const [items, setItems] = useState<Item[]>([]);
90	  const [cursor, setCursor] = useState<string | null>(null);
91	  const [hasMore, setHasMore] = useState(true);
92	  const [loading, setLoading] = useState(false);
93	  const [ready, setReady] = useState(false);
94	  const [viewIndex, setViewIndex] = useState<number | null>(null);
95	  // A deep-linked photo (notification tap) opens straight in the viewer, even if
96	  // it isn't on the first grid page — fetched on mount into a single-item viewer.
97	  const [deepPhoto, setDeepPhoto] = useState<ViewerItem | null>(null);
98	  const mode = useNameMode();
99	  const [allUsers, setAllUsers] = useState<ViewerUser[]>([]);
100	
101	  // Filters (mirror the original). Arriving from a photo-upload activity item
102	  // (initialBulkId) narrows the gallery to just that upload batch, with a
103	  // clearable "From this upload" chip to return to the full collection.
104	  const [sort, setSort] = useState<Sort>(initialBulkId ? "uploaded" : "taken");
105	  const [year, setYear] = useState<string>("all");
106	  const [taggedIds, setTaggedIds] = useState<Set<string>>(new Set());
107	  const [bulk, setBulk] = useState<string | null>(initialBulkId ?? null);
108	  const [showFilterUsers, setShowFilterUsers] = useState(false);
109	  const [years, setYears] = useState<number[]>([]);
110	  const [taggedUsers, setTaggedUsers] = useState<{ userId: string; displayName: string }[]>([]);
111	  const [reloadKey, setReloadKey] = useState(0);
112	  const [upload, setUpload] = useState<{ done: number; total: number } | null>(null);
113	  const fileRef = useRef<HTMLInputElement>(null);
114	
115	  const taggedKey = [...taggedIds].sort().join(",");
116	  const filtersActive = year !== "all" || taggedIds.size > 0 || !!bulk;
117	
118	  const params = useCallback(
119	    (cur?: string) => {
120	      const p = new URLSearchParams({ orgId });
121	      if (sort === "uploaded") p.set("sort", "uploaded");
122	      if (year !== "all") p.set("year", year);
123	      if (taggedIds.size) p.set("taggedUserIds", [...taggedIds].join(","));
124	      if (bulk) p.set("bulkId", bulk);
125	      if (cur) p.set("cursor", cur);
126	      return p.toString();
127	    },
128	    [orgId, sort, year, taggedIds, bulk],
129	  );
130	
131	  // Filter options.
132	  useEffect(() => {
133	    let cancelled = false;
134	    (async () => {
135	      try {
136	        const res = await fetch(`/api/v2/gallery/facets?orgId=${orgId}`);
137	        const d = res.ok ? await res.json() : { years: [], taggedUsers: [] };
138	        if (cancelled) return;
139	        setYears(d.years || []);
140	        setTaggedUsers(d.taggedUsers || []);
141	      } catch {
142	        /* ignore */
143	      }
144	    })();
145	    return () => {
146	      cancelled = true;
147	    };
148	  }, [orgId]);
149	
150	  // Members (for the viewer's tag picker + tag-name resolution).
151	  useEffect(() => {
152	    let cancelled = false;
153	    (async () => {
154	      const res = await fetch(`/api/v2/chat/members?orgId=${orgId}&includeSelf=1`);
155	      const d = res.ok ? await res.json() : { members: [] };
156	      if (cancelled) return;
157	      setAllUsers(
158	        (d.members || []).map((m: { userId: string; displayName: string; avatarUrl: string | null }) => ({
159	          id: m.userId,
160	          display_name: m.displayName,
161	          avatar_url: m.avatarUrl,
162	        })),
163	      );
164	    })();
165	    return () => {
166	      cancelled = true;
167	    };
168	  }, [orgId]);
169	
170	  // The "add photos" + lives in the shared drawer header now (EventShell).
171	  useEffect(() => {
172	    const handler = () => {
173	      if (!upload) fileRef.current?.click();
174	    };
175	    window.addEventListener("ui:photos-add", handler);
176	    return () => window.removeEventListener("ui:photos-add", handler);
177	  }, [upload]);
178	
179	  const viewerItems = useMemo(() => items.map((it) => toViewerItem(it, userId, mode)), [items, userId, mode]);
180	
181	  // Deep-link: open the specific photo from a notification tap.
182	  useEffect(() => {
183	    if (!initialPhotoId) return;
184	    let cancelled = false;
185	    (async () => {
186	      const res = await fetch(`/api/v2/gallery/${initialPhotoId}`);
187	      if (!res.ok) return;
188	      const d = await res.json();
189	      if (cancelled || !d.item) return;
190	      setDeepPhoto(toViewerItem(d.item as Item, userId, mode));
191	    })();
192	    return () => {
193	      cancelled = true;
194	    };
195	  }, [initialPhotoId, userId, mode]);
196	
197	  // Load / reload on filter change.
198	  useEffect(() => {
199	    let cancelled = false;
200	    setReady(false);
201	    (async () => {
202	      try {
203	        const res = await fetch(`/api/v2/gallery?${params()}`);
204	        const d = res.ok ? await res.json() : { items: [], nextCursor: null };
205	        if (cancelled) return;
206	        setItems(d.items || []);
207	        setCursor(d.nextCursor);
208	        setHasMore(!!d.nextCursor);
209	      } finally {
210	        if (!cancelled) setReady(true);
211	      }
212	    })();
213	    return () => {
214	      cancelled = true;
215	    };
216	    // eslint-disable-next-line react-hooks/exhaustive-deps
217	  }, [orgId, sort, year, taggedKey, bulk, reloadKey]);
218	
219	  const loadMore = useCallback(async () => {
220	    if (loading || !hasMore || !cursor) return;
221	    setLoading(true);
222	    try {
223	      const res = await fetch(`/api/v2/gallery?${params(cursor)}`);
224	      const d = res.ok ? await res.json() : { items: [], nextCursor: null };
225	      setItems((cur) => {
226	        const seen = new Set(cur.map((i) => i.id));
227	        return [...cur, ...(d.items || []).filter((i: Item) => !seen.has(i.id))];
228	      });
229	      setCursor(d.nextCursor);
230	      setHasMore(!!d.nextCursor);
231	    } finally {
232	      setLoading(false);
233	    }
234	  }, [params, cursor, hasMore, loading]);
235	
236	  // Realtime: prepend new items only when no filters narrow the view.
237	  useEffect(() => {
238	    let cancelled = false;
239	    let sb: Awaited<ReturnType<typeof v2RealtimeClient>> | null = null;
240	    let channel: RealtimeChannel | null = null;
241	    (async () => {
242	      sb = await v2RealtimeClient();
243	      if (cancelled) return;
244	      channel = sb
245	        .channel(`v2-gallery-${orgId}`)
246	        .on(
247	          "postgres_changes",
248	          { event: "INSERT", schema: "public", table: "v2_gallery_items", filter: `org_id=eq.${orgId}` },
249	          (payload) => {
250	            if (filtersActive) return;
251	            const it = payload.new as Item;
252	            setItems((cur) => (cur.some((x) => x.id === it.id) ? cur : [it, ...cur]));
253	          },
254	        )
255	        .subscribe();
256	    })();
257	    return () => {
258	      cancelled = true;
259	      if (sb && channel) sb.removeChannel(channel);
260	    };
261	  }, [orgId, filtersActive]);
262	
263	  function onScroll(e: React.UIEvent<HTMLDivElement>) {
264	    const el = e.currentTarget;
265	    if (el.scrollHeight - el.scrollTop - el.clientHeight < 400) loadMore();
266	  }
267	
268	  // Upload one file: compress (photo/video), extract date + video thumbnail,
269	  // signed direct-to-storage upload, then record the item.
270	  async function uploadOne(file: File, bulkId: string): Promise<{ thumb: string | null } | null> {
271	    const isVideo = file.type.startsWith("video/");
272	    let blob: Blob;
273	    let width: number | null = null;
274	    let height: number | null = null;
275	    let thumbBlob: Blob | null = null;
276	    let takenAt: string | null = null;
277	    try {
278	      if (isVideo) {
279	        takenAt = (await extractVideoDate(file))?.toISOString() ?? null;
280	        try {
281	          const c = await compressVideo(file);
282	          blob = c.blob;
283	          width = c.width;
284	          height = c.height;
285	        } catch {
286	          blob = file;
287	        }
288	        try {
289	          thumbBlob = await extractVideoFrame(file);
290	        } catch {
291	          thumbBlob = null;
292	        }
293	      } else {
294	        takenAt = (await extractExifDate(file))?.toISOString() ?? null;
295	        const c = await compressImage(file, 1280, 0.8);
296	        blob = c.blob;
297	        width = c.width;
298	        height = c.height;
299	      }
300	
301	      const urlRes = await fetch("/api/v2/gallery/upload-url", {
302	        method: "POST",
303	        headers: { "Content-Type": "application/json" },
304	        body: JSON.stringify({ orgId, mediaType: isVideo ? "video" : "photo", fileName: file.name }),
305	      });
306	      if (!urlRes.ok) throw new Error();
307	      const u = await urlRes.json();
308	
309	      const put = await fetch(u.signedUrl, {
310	        method: "PUT",
311	        body: blob,
312	        headers: { "content-type": blob.type || (isVideo ? "video/mp4" : "image/jpeg") },
313	      });
314	      if (!put.ok) throw new Error();
315	
316	      let thumbnailUrl: string | null = null;
317	      if (isVideo && thumbBlob && u.thumbSignedUrl) {
318	        await fetch(u.thumbSignedUrl, { method: "PUT", body: thumbBlob, headers: { "content-type": "image/jpeg" } });
319	        thumbnailUrl = u.thumbPublicUrl;
320	      }
321	
322	      await fetch("/api/v2/gallery", {
323	        method: "POST",
324	        headers: { "Content-Type": "application/json" },
325	        body: JSON.stringify({
326	          orgId,
327	          mediaUrl: u.publicUrl,
328	          thumbnailUrl,
329	          mediaType: isVideo ? "video" : "photo",
330	          takenAt,
331	          width,
332	          height,
333	          bulkId,
334	        }),
335	      });
336	      return { thumb: thumbnailUrl || u.publicUrl };
337	    } catch {
338	      return null;
339	    }
340	  }
341	
342	  async function handleFiles(list: FileList | null) {
343	    const files = list ? Array.from(list) : [];
344	    if (files.length === 0) return;
345	    const bulkId = crypto.randomUUID();
346	    setUpload({ done: 0, total: files.length });
347	    // A few thumbnails to preview the batch in the activity feed (leading image +
348	    // a small strip). Parallel workers finish out of order — any few will do.
349	    const thumbs: string[] = [];
350	    let done = 0;
351	    const queue = [...files];
352	    const worker = async () => {
353	      while (queue.length) {
354	        const f = queue.shift()!;
355	        const r = await uploadOne(f, bulkId);
356	        if (r?.thumb && thumbs.length < 4) thumbs.push(r.thumb);
357	        done += 1;
358	        setUpload({ done, total: files.length });
359	      }
360	    };
361	    await Promise.all([worker(), worker(), worker()]);
362	    await fetch("/api/v2/gallery/log-upload", {
363	      method: "POST",
364	      headers: { "Content-Type": "application/json" },
365	      body: JSON.stringify({ orgId, count: files.length, imageUrl: thumbs[0] ?? null, thumbs, bulkId }),
366	    }).catch(() => {});
367	    setUpload(null);
368	    setReloadKey((k) => k + 1);
369	  }
370	
371	  function toggleTagged(id: string) {
372	    setTaggedIds((cur) => {
373	      const next = new Set(cur);
374	      if (next.has(id)) next.delete(id);
375	      else next.add(id);
376	      return next;
377	    });
378	  }
379	
380	  return (
381	    <div className={styles.wrap}>
382	      <div className={styles.filters}>
383	        {bulk && (
384	          <button type="button" className={styles.bulkChip} onClick={() => setBulk(null)}>
385	            From this upload
386	            <svg width="12" height="12" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24">
387	              <path d="M6 18L18 6M6 6l12 12" />
388	            </svg>
389	          </button>
390	        )}
391	        <button
392	          type="button"
393	          className={styles.sortBtn}
394	          onClick={() => setSort((s) => (s === "taken" ? "uploaded" : "taken"))}
395	        >
396	          <svg width="13" height="13" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24">
397	            <path d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4" />
398	          </svg>
399	          {sort === "taken" ? "Date Taken" : "Date Uploaded"}
400	        </button>
401	
402	        {years.length > 0 && (
403	          <select
404	            className={styles.yearSelect}
405	            data-on={year !== "all" || undefined}
406	            value={year}
407	            onChange={(e) => setYear(e.target.value)}
408	          >
409	            <option value="all">All years</option>
410	            {years.map((y) => (
411	              <option key={y} value={String(y)}>
412	                {y}
413	              </option>
414	            ))}
415	          </select>
416	        )}
417	
418	        {taggedUsers.length > 0 && (
419	          <button
420	            type="button"
421	            className={styles.loozerBtn}
422	            data-on={taggedIds.size > 0 || undefined}
423	            onClick={() => setShowFilterUsers((v) => !v)}
424	          >
425	            <svg width="14" height="14" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24">
426	              <path d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
427	            </svg>
428	            {taggedIds.size > 0 ? taggedIds.size : "Loozers"}
429	          </button>
430	        )}
431	
432	        {showFilterUsers && taggedIds.size > 0 && (
433	          <button type="button" className={styles.clearBtn} onClick={() => setTaggedIds(new Set())}>
434	            Clear
435	          </button>
436	        )}
437	      </div>
438	
439	      {showFilterUsers && taggedUsers.length > 0 && (
440	        <div className={styles.loozerPanel}>
441	          <div className={styles.loozerHead}>
442	            <span className={styles.loozerTitle}>Filter by Loozer</span>
443	            <button type="button" className={styles.loozerDone} onClick={() => setShowFilterUsers(false)}>
444	              Done
445	            </button>
446	          </div>
447	          <div className={styles.loozerPicker}>
448	            {taggedUsers.map((u) => (
449	              <button
450	                key={u.userId}
451	                type="button"
452	                className={styles.loozerChip}
453	                data-on={taggedIds.has(u.userId) || undefined}
454	                onClick={() => toggleTagged(u.userId)}
455	              >
456	                {u.displayName}
457	              </button>
458	            ))}
459	          </div>
460	        </div>
461	      )}
462	
463	      {ready && items.length === 0 ? (
464	        <p className={styles.empty}>No photos match.</p>
465	      ) : (
466	        <div className={styles.scrollArea} onScroll={onScroll}>
467	          <div className={styles.grid}>
468	            {items.map((it, i) => (
469	              <button
470	                key={it.id}
471	                type="button"
472	                className={styles.cell}
473	                onClick={() => setViewIndex(i)}
474	              >
475	                <img src={it.thumbnail_url || it.media_url} alt="" loading="lazy" />
476	                {it.media_type === "video" && (
477	                  <span className={styles.playBadge} aria-hidden>
478	                    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
479	                      <path d="M8 5v14l11-7z" />
480	                    </svg>
481	                  </span>
482	                )}
483	              </button>
484	            ))}
485	          </div>
486	        </div>
487	      )}
488	
489	      {/* Add photos (single or bulk) — triggered by the header + (ui:photos-add). */}
490	      <input
491	        ref={fileRef}
492	        type="file"
493	        accept="image/*,video/*"
494	        multiple
495	        hidden
496	        onChange={(e) => {
497	          handleFiles(e.target.files);
498	          e.target.value = "";
499	        }}
500	      />
501	
502	      {upload && (
503	        <div className={styles.uploadToast}>
504	          <span className={styles.uploadSpinner} />
505	          Uploading {upload.done}/{upload.total}…
506	        </div>
507	      )}
508	
509	      {viewIndex !== null && (
510	        <MediaViewer
511	          items={viewerItems}
512	          initialIndex={viewIndex}
513	          orgId={orgId}
514	          userId={userId}
515	          isAdmin={isAdmin}
516	          allUsers={allUsers}
517	          onClose={() => setViewIndex(null)}
518	          onDelete={(id) => setItems((cur) => cur.filter((it) => it.id !== id))}
519	        />
520	      )}
521	
522	      {deepPhoto && (
523	        <MediaViewer
524	          items={[deepPhoto]}
525	          initialIndex={0}
526	          orgId={orgId}
527	          userId={userId}
528	          isAdmin={isAdmin}
529	          allUsers={allUsers}
530	          onClose={() => setDeepPhoto(null)}
531	          onDelete={(id) => {
532	            setDeepPhoto(null);
533	            setItems((cur) => cur.filter((it) => it.id !== id));
534	          }}
535	        />
536	      )}
537	    </div>
538	  );
539	}
