1	"use client";
2	
3	import { useState, useRef, useCallback, useEffect, useMemo } from "react";
4	import { v2RealtimeClient } from "@/lib/v2/supabase-browser";
5	import type { RealtimeChannel } from "@supabase/supabase-js";
6	import { useNameMode } from "./NameMode";
7	import { pickName } from "@/lib/v2/profile";
8	/* eslint-disable @next/next/no-img-element */
9	
10	// ─── Types ───────────────────────────────────────────────────────────────────
11	
12	export interface ViewerItem {
13	  id: string;
14	  media_url: string;
15	  thumbnail_url: string | null;
16	  media_type: "photo" | "video";
17	  caption: string | null;
18	  width: number | null;
19	  height: number | null;
20	  created_at: string;
21	  taken_at: string | null;
22	  uploader_id: string;
23	  uploader: { display_name: string; avatar_url: string | null };
24	  reactions: Record<string, { count: number; hasReacted: boolean }>;
25	  reactionCount: number;
26	  tags: string[];
27	  commentCount: number;
28	}
29	
30	export interface ViewerUser {
31	  id: string;
32	  display_name: string;
33	  avatar_url: string | null;
34	}
35	
36	function getInitials(name: string): string {
37	  const parts = name.trim().split(/\s+/);
38	  if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
39	  return (name[0] || "?").toUpperCase();
40	}
41	function getDistance(t1: React.Touch, t2: React.Touch) {
42	  return Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
43	}
44	// Short stamp for comment rows (now / 5m / 3h / Mar 4).
45	function commentStamp(s: string, now = new Date()): string {
46	  const mins = Math.floor((now.getTime() - new Date(s).getTime()) / 60000);
47	  if (mins < 1) return "now";
48	  if (mins < 60) return `${mins}m`;
49	  const hrs = Math.floor(mins / 60);
50	  if (hrs < 24) return `${hrs}h`;
51	  return new Date(s).toLocaleDateString(undefined, { month: "short", day: "numeric" });
52	}
53	// Longer stamp for the uploader line (Just now / 5m ago / … / date).
54	function mediaStamp(s: string, now = new Date()): string {
55	  const mins = Math.floor((now.getTime() - new Date(s).getTime()) / 60000);
56	  if (mins < 1) return "Just now";
57	  if (mins < 60) return `${mins}m ago`;
58	  const hrs = Math.floor(mins / 60);
59	  if (hrs < 24) return `${hrs}h ago`;
60	  const days = Math.floor(hrs / 24);
61	  if (days < 7) return `${days}d ago`;
62	  return new Date(s).toLocaleDateString();
63	}
64	const one = <T,>(v: T | T[] | null | undefined): T | null => (Array.isArray(v) ? v[0] ?? null : v ?? null);
65	
66	// ─── MediaPanel: a single photo (pinch-zoom) or video ────────────────────────
67	
68	function MediaPanel({
69	  item,
70	  isActive,
71	  videoRefCallback,
72	  onZoomChange,
73	}: {
74	  item: ViewerItem;
75	  isActive: boolean;
76	  videoRefCallback: (id: string, el: HTMLVideoElement | null) => void;
77	  onZoomChange: (zoomed: boolean) => void;
78	}) {
79	  const [videoLoading, setVideoLoading] = useState(false);
80	  const [scale, setScale] = useState(1);
81	  const [offset, setOffset] = useState({ x: 0, y: 0 });
82	  const [isSnapBack, setIsSnapBack] = useState(false);
83	  const gestureRef = useRef({
84	    isPinching: false,
85	    isPanning: false,
86	    initialDist: 0,
87	    initialScale: 1,
88	    initialOffset: { x: 0, y: 0 },
89	    initialMid: { x: 0, y: 0 },
90	    panStart: { x: 0, y: 0 },
91	    panStartOffset: { x: 0, y: 0 },
92	  });
93	
94	  useEffect(() => {
95	    if (isActive) return;
96	    const raf = requestAnimationFrame(() => {
97	      setScale(1);
98	      setOffset({ x: 0, y: 0 });
99	      onZoomChange(false);
100	    });
101	    return () => cancelAnimationFrame(raf);
102	  }, [isActive, onZoomChange]);
103	
104	  if (item.media_type === "video") {
105	    return (
106	      <>
107	        <video
108	          ref={(el) => videoRefCallback(item.id, el)}
109	          src={item.media_url}
110	          poster={item.thumbnail_url || undefined}
111	          className="max-w-full max-h-full object-contain"
112	          autoPlay={isActive}
113	          loop
114	          playsInline
115	          preload="auto"
116	          onWaiting={() => setVideoLoading(true)}
117	          onPlaying={() => setVideoLoading(false)}
118	          onCanPlay={() => setVideoLoading(false)}
119	        />
120	        {videoLoading && isActive && (
121	          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
122	            <div className="w-10 h-10 border-3 border-white/30 border-t-white rounded-full animate-spin" />
123	          </div>
124	        )}
125	      </>
126	    );
127	  }
128	
129	  const handleTouchStart = (e: React.TouchEvent) => {
130	    const g = gestureRef.current;
131	    if (e.touches.length === 2) {
132	      e.stopPropagation();
133	      g.isPinching = true;
134	      g.isPanning = false;
135	      g.initialDist = getDistance(e.touches[0], e.touches[1]);
136	      g.initialScale = scale;
137	      g.initialOffset = { x: offset.x, y: offset.y };
138	      g.initialMid = {
139	        x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
140	        y: (e.touches[0].clientY + e.touches[1].clientY) / 2,
141	      };
142	      setIsSnapBack(false);
143	      onZoomChange(true);
144	    } else if (e.touches.length === 1 && scale > 1) {
145	      e.stopPropagation();
146	      g.isPanning = true;
147	      g.panStart = { x: e.touches[0].clientX, y: e.touches[0].clientY };
148	      g.panStartOffset = { x: offset.x, y: offset.y };
149	    }
150	  };
151	
152	  const handleTouchMove = (e: React.TouchEvent) => {
153	    const g = gestureRef.current;
154	    if (g.isPinching && e.touches.length >= 2) {
155	      e.stopPropagation();
156	      e.preventDefault();
157	      const dist = getDistance(e.touches[0], e.touches[1]);
158	      const newScale = Math.min(4, Math.max(1, g.initialScale * (dist / g.initialDist)));
159	      const mid = {
160	        x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
161	        y: (e.touches[0].clientY + e.touches[1].clientY) / 2,
162	      };
163	      setScale(newScale);
164	      setOffset({
165	        x: g.initialOffset.x + (mid.x - g.initialMid.x),
166	        y: g.initialOffset.y + (mid.y - g.initialMid.y),
167	      });
168	    } else if (g.isPanning && e.touches.length === 1) {
169	      e.stopPropagation();
170	      e.preventDefault();
171	      setOffset({
172	        x: g.panStartOffset.x + (e.touches[0].clientX - g.panStart.x),
173	        y: g.panStartOffset.y + (e.touches[0].clientY - g.panStart.y),
174	      });
175	    }
176	  };
177	
178	  const handleTouchEnd = (e: React.TouchEvent) => {
179	    const g = gestureRef.current;
180	    if (g.isPinching && e.touches.length < 2) {
181	      g.isPinching = false;
182	      if (scale < 1.1) {
183	        setIsSnapBack(true);
184	        setScale(1);
185	        setOffset({ x: 0, y: 0 });
186	        onZoomChange(false);
187	        setTimeout(() => setIsSnapBack(false), 200);
188	      }
189	    }
190	    if (g.isPanning && e.touches.length === 0) g.isPanning = false;
191	  };
192	
193	  const hasAspectRatio = item.width && item.height;
194	
195	  return (
196	    <div
197	      className="relative flex items-center justify-center w-full h-full"
198	      onTouchStart={handleTouchStart}
199	      onTouchMove={handleTouchMove}
200	      onTouchEnd={handleTouchEnd}
201	    >
202	      <div
203	        style={{
204	          transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`,
205	          transition: isSnapBack ? "transform 0.2s ease-out" : "none",
206	          ...(hasAspectRatio
207	            ? { aspectRatio: `${item.width}/${item.height}`, width: "100vw", maxWidth: "100vw", maxHeight: "100dvh" }
208	            : {}),
209	        }}
210	        className={hasAspectRatio ? "relative" : "relative flex items-center justify-center"}
211	      >
212	        <img
213	          src={item.media_url}
214	          alt={item.caption || ""}
215	          className={hasAspectRatio ? "w-full h-full object-contain" : "max-w-full max-h-full object-contain"}
216	        />
217	      </div>
218	    </div>
219	  );
220	}
