586	export default function MediaViewer({
587	  items,
588	  initialIndex,
589	  userId,
590	  isAdmin,
591	  allUsers,
592	  onClose,
593	  onDelete,
594	  initialShowComments = false,
595	}: {
596	  items: ViewerItem[];
597	  initialIndex: number;
598	  orgId: string;
599	  userId: string;
600	  isAdmin: boolean;
601	  allUsers: ViewerUser[];
602	  onClose: () => void;
603	  onDelete: (itemId: string) => void;
604	  initialShowComments?: boolean;
605	}) {
606	  // Internal, mutable copy so reaction/tag/caption edits survive parent re-renders.
607	  const [list, setList] = useState<ViewerItem[]>(items);
608	  const [currentIndex, setCurrentIndex] = useState(initialIndex);
609	  const [showOverlay, setShowOverlay] = useState(true);
610	  const [showComments, setShowComments] = useState(initialShowComments);
611	  const [showReactions, setShowReactions] = useState(false);
612	  const [showTags, setShowTags] = useState(false);
613	  const [showMenu, setShowMenu] = useState(false);
614	  const [editingCaption, setEditingCaption] = useState(false);
615	  const [captionDraft, setCaptionDraft] = useState("");
616	  const [isMuted, setIsMuted] = useState(true);
617	  const [showPlayPauseIcon, setShowPlayPauseIcon] = useState(false);
618	  const [isPaused, setIsPaused] = useState(false);
619	  const [isZoomed, setIsZoomed] = useState(false);
620	  const [heartAnimations, setHeartAnimations] = useState<{ id: number; x: number; y: number }[]>([]);
621	  const [confirmDelete, setConfirmDelete] = useState(false);
622	
623	  const [swipeOffset, setSwipeOffset] = useState(0);
624	  const [isSettling, setIsSettling] = useState(false);
625	  const touchStartY = useRef(0);
626	  const touchDelta = useRef(0);
627	  const touchFingers = useRef(0);
628	  const playPauseTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
629	  const lastTapTime = useRef(0);
630	  const singleTapTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
631	  const heartIdRef = useRef(0);
632	
633	  const videoRefs = useRef<Record<string, HTMLVideoElement | null>>({});
634	  const isMutedRef = useRef(isMuted);
635	  useEffect(() => {
636	    isMutedRef.current = isMuted;
637	  }, [isMuted]);
638	
639	  const videoRefCallback = useCallback((id: string, el: HTMLVideoElement | null) => {
640	    if (el) {
641	      videoRefs.current[id] = el;
642	      el.muted = isMutedRef.current;
643	    } else {
644	      delete videoRefs.current[id];
645	    }
646	  }, []);
647	
648	  const handleZoomChange = useCallback((zoomed: boolean) => setIsZoomed(zoomed), []);
649	
650	  const mutateItem = useCallback((index: number, patch: Partial<ViewerItem>) => {
651	    setList((prev) => prev.map((it, i) => (i === index ? { ...it, ...patch } : it)));
652	  }, []);
653	
654	  const item = list[currentIndex];
655	
656	  useEffect(() => {
657	    if (!item) onClose();
658	  }, [item, onClose]);
659	
660	  const canDelete = !!item && (item.uploader_id === userId || isAdmin);
661	  const drawerOpen = showComments || showReactions || showTags;
662	
663	  const panels = useMemo(() => {
664	    const result: { item: ViewerItem; position: number }[] = [];
665	    if (currentIndex > 0) result.push({ item: list[currentIndex - 1], position: -1 });
666	    if (list[currentIndex]) result.push({ item: list[currentIndex], position: 0 });
667	    if (currentIndex < list.length - 1) result.push({ item: list[currentIndex + 1], position: 1 });
668	    return result;
669	  }, [currentIndex, list]);
670	
671	  // Video playback management.
672	  useEffect(() => {
673	    const active = list[currentIndex];
674	    for (const [id, el] of Object.entries(videoRefs.current)) {
675	      if (!el) continue;
676	      if (id === active?.id) {
677	        el.muted = isMuted;
678	        const p = el.play();
679	        if (p) p.catch(() => {
680	          el.muted = true;
681	          el.play().catch(() => {});
682	        });
683	      } else {
684	        el.pause();
685	      }
686	    }
687	    const raf = requestAnimationFrame(() => setIsPaused(false));
688	    return () => cancelAnimationFrame(raf);
689	  }, [currentIndex, list, isMuted]);
690	
691	  const toggleMute = useCallback(() => {
692	    setIsMuted((m) => {
693	      const next = !m;
694	      for (const el of Object.values(videoRefs.current)) if (el) el.muted = next;
695	      return next;
696	    });
697	  }, []);
698	
699	  // Soft-prefetch neighbours.
700	  useEffect(() => {
701	    const cleanup: (() => void)[] = [];
702	    for (const idx of [currentIndex - 2, currentIndex - 3, currentIndex + 2, currentIndex + 3]) {
703	      const adj = list[idx];
704	      if (!adj) continue;
705	      if (adj.media_type === "video") {
706	        const link = document.createElement("link");
707	        link.rel = "preload";
708	        link.as = "fetch";
709	        link.href = adj.media_url;
710	        document.head.appendChild(link);
711	        cleanup.push(() => link.remove());
712	      } else {
713	        const img = new Image();
714	        img.src = adj.media_url;
715	      }
716	    }
717	    return () => cleanup.forEach((fn) => fn());
718	  }, [currentIndex, list]);
719	
720	  const toggleLike = (tapX: number, tapY: number) => {
721	    const heart = "❤️";
722	    const cur = list[currentIndex];
723	    if (!cur) return;
724	    const r = cur.reactions[heart];
725	    const isLiked = r?.hasReacted ?? false;
726	    const reactions = { ...cur.reactions };
727	    let count = cur.reactionCount;
728	    if (isLiked) {
729	      if (r.count <= 1) delete reactions[heart];
730	      else reactions[heart] = { count: r.count - 1, hasReacted: false };
731	      count--;
732	    } else {
733	      reactions[heart] = { count: (r?.count ?? 0) + 1, hasReacted: true };
734	      count++;
735	      const id = heartIdRef.current++;
736	      setHeartAnimations((prev) => [...prev, { id, x: tapX, y: tapY }]);
737	      setTimeout(() => setHeartAnimations((prev) => prev.filter((h) => h.id !== id)), 800);
738	    }
739	    mutateItem(currentIndex, { reactions, reactionCount: count });
740	    fetch(`/api/v2/gallery/${cur.id}/reactions`, {
741	      method: isLiked ? "DELETE" : "POST",
742	      headers: { "Content-Type": "application/json" },
743	      body: JSON.stringify({ emoji: heart }),
744	    }).catch(() => {});
745	  };
