751	    touchStartY.current = e.touches[0].clientY;
752	    touchDelta.current = 0;
753	  };
754	  const handleTouchMove = (e: React.TouchEvent) => {
755	    if (drawerOpen || isSettling) return;
756	    if (e.touches.length >= 2 || isZoomed) return;
757	    e.preventDefault();
758	    const delta = e.touches[0].clientY - touchStartY.current;
759	    touchDelta.current = delta;
760	    const atStart = currentIndex === 0 && delta > 0;
761	    const atEnd = currentIndex === list.length - 1 && delta < 0;
762	    setSwipeOffset(atStart || atEnd ? delta * 0.3 : delta);
763	  };
