1	"use client";
2	
3	import { useState } from "react";
4	
5	const EMOJI_OPTIONS = [
6	  { emoji: "\u2764\uFE0F", label: "Love" },
7	  { emoji: "\uD83D\uDC4D", label: "Thumbs up" },
8	  { emoji: "\uD83D\uDC4E", label: "Thumbs down" },
9	  { emoji: "\uD83D\uDE02", label: "Haha" },
10	  { emoji: "\u2757\uFE0F", label: "Exclamation" },
11	  { emoji: "\u2753", label: "Question" },
12	];
13	
14	export function MediaReactions({
15	  itemId,
16	  reactions,
17	  onClose,
18	  onReactionChanged,
19	}: {
20	  itemId: string;
21	  reactions: Record<string, { count: number; hasReacted: boolean }>;
22	  onClose: () => void;
23	  onReactionChanged: (
24	    newReactions: Record<string, { count: number; hasReacted: boolean }>
25	  ) => void;
26	}) {
27	  const [localReactions, setLocalReactions] = useState(reactions);
28	
29	  const toggleReaction = async (emoji: string) => {
