3	
4	/**
5	 * Reactions on a gallery item.
6	 *   POST   { emoji } — add (idempotent).
7	 *   DELETE { emoji } — remove the caller's reaction.
8	 * Auth: bearer/cookie; org-membership gated.
9	 */
10	export async function POST(
11	  request: Request,
12	  { params }: { params: Promise<{ itemId: string }> },
13	) {
14	  const { itemId } = await params;
15	  const a = await resolveGalleryItem(request, itemId);
16	  if ("error" in a) return NextResponse.json({ error: a.error }, { status: a.status });
17	
18	  let body: { emoji?: string };
19	  try {
20	    body = await request.json();
21	  } catch {
22	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
23	  }
24	  if (!body.emoji) return NextResponse.json({ error: "emoji required" }, { status: 400 });
25	
26	  const { error } = await a.admin
27	    .from("v2_gallery_reactions")
28	    .upsert({ item_id: itemId, user_id: a.userId, emoji: body.emoji }, { onConflict: "item_id,user_id,emoji" });
29	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
30	  return NextResponse.json({ ok: true });
31	}
32	
33	export async function DELETE(
34	  request: Request,
35	  { params }: { params: Promise<{ itemId: string }> },
36	) {
37	  const { itemId } = await params;
38	  const a = await resolveGalleryItem(request, itemId);
39	  if ("error" in a) return NextResponse.json({ error: a.error }, { status: a.status });
40	
41	  let body: { emoji?: string };
42	  try {
43	    body = await request.json();
44	  } catch {
45	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
46	  }
47	  if (!body.emoji) return NextResponse.json({ error: "emoji required" }, { status: 400 });
48	
49	  const { error } = await a.admin
50	    .from("v2_gallery_reactions")
51	    .delete()
52	    .eq("item_id", itemId)
53	    .eq("user_id", a.userId)
54	    .eq("emoji", body.emoji);
55	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
56	  return NextResponse.json({ ok: true });
57	}
