/** Article hero images allow GIF (fun) on top of the usual raster formats. */
function extForArticleImage(mime: string): string | null {
  switch (mime) {
    case "image/png":
      return "png";
    case "image/jpeg":
      return "jpg";
    case "image/webp":
      return "webp";
    case "image/gif":
