import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { hasPermission } from "@/lib/v2/permissions-server";
import { broadcastIfNewlyLive } from "@/lib/v2/articles";

/**
 * @swagger
 * /api/v2/articles:
 *   get:
 *     tags: [Articles]
 *     summary: List an org's articles (incl. drafts) for admin management
 *     description: Requires the manage_articles permission (or org owner/admin).
 *     parameters:
 *       - in: query
 *         name: orgId
 *         required: true
 *         schema: { type: string }
 *   post:
 *     tags: [Articles]
 *     summary: Create an article (draft, scheduled, or published)
 */

const ADMIN_SELECT =
  "id, org_id, event_id, title, content, image_url, image_focal_x, image_focal_y, publish_at, pinned_at, notify_on_publish, view_count, created_at, updated_at, author_id, author:v2_profiles(display_name, first_name, last_name, avatar_url)";

/** Clamp a focal coordinate to 0–100 (default 50). */
function focal(v: unknown): number {
  const n = Number(v);
  if (!Number.isFinite(n)) return 50;
  return Math.max(0, Math.min(100, Math.round(n)));
}

export async function GET(request: Request) {
  const url = new URL(request.url);
  const orgId = url.searchParams.get("orgId");
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  if (!orgId) return NextResponse.json({ error: "orgId required" }, { status: 400 });

  const admin = v2AdminClient();
  if (!(await hasPermission(admin, userId, orgId, "manage_articles"))) {
    return NextResponse.json({ error: "Not allowed" }, { status: 403 });
  }

  const { data, error } = await admin
    .from("v2_articles")
    .select(ADMIN_SELECT)
    .eq("org_id", orgId)
    .order("publish_at", { ascending: false, nullsFirst: true })
    .order("created_at", { ascending: false });
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  return NextResponse.json({ articles: data ?? [] });
}

export async function POST(request: Request) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });

  let body: {
    orgId?: string;
    event_id?: string | null;
    title?: string;
    content?: string;
    image_url?: string | null;
    image_focal_x?: number;
    image_focal_y?: number;
    publish_at?: string | null;
    notify_on_publish?: boolean;
  };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }

  const orgId = body.orgId;
  if (!orgId) return NextResponse.json({ error: "orgId required" }, { status: 400 });
  const title = (body.title || "").trim();
  if (!title) return NextResponse.json({ error: "A title is required" }, { status: 400 });

  const admin = v2AdminClient();
  if (!(await hasPermission(admin, userId, orgId, "manage_articles"))) {
    return NextResponse.json({ error: "Not allowed" }, { status: 403 });
  }

  const nowIso = new Date().toISOString();
  const { data, error } = await admin
    .from("v2_articles")
    .insert({
      org_id: orgId,
      event_id: body.event_id ?? null,
      author_id: userId,
      title,
      content: body.content ?? "",
      image_url: body.image_url ?? null,
      image_focal_x: focal(body.image_focal_x),
      image_focal_y: focal(body.image_focal_y),
      publish_at: body.publish_at ?? null,
      notify_on_publish: body.notify_on_publish ?? true,
      created_at: nowIso,
      updated_at: nowIso,
    })
    .select("id")
    .single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  // If it's created already-live, broadcast (activity feed always; push if opted in).
  await broadcastIfNewlyLive(admin, data.id);

  return NextResponse.json({ id: data.id });
}

import { redirect } from "next/navigation";
import Link from "next/link";
import { v2ServerClient } from "@/lib/v2/supabase";
import { getPlatformContext } from "@/lib/v2/context";
import { pickName } from "@/lib/v2/profile";
import { stripMarkdown } from "@/lib/v2/text";
import { loadResolvedFeatures } from "@/lib/v2/features-server";
import { isFeatureVisible } from "@/lib/v2/features";
import styles from "@/app/new/new.module.css";
/* eslint-disable @next/next/no-img-element */

interface AuthorRef {
  display_name: string;
  first_name: string | null;
  last_name: string | null;
  avatar_url: string | null;
}
interface ArticleRow {
  id: string;
  title: string;
  content: string | null;
  image_url: string | null;
  image_focal_x: number | null;
  image_focal_y: number | null;
  publish_at: string;
  author: AuthorRef | AuthorRef[] | null;
}

/**
 * The Articles index — every published article for the org, newest first. Reached
 * from the "Everything" launcher (feature: articles) or a pinned bottom-bar slot.
 * Author names honor the org's name-display mode.
 */
export default async function ArticlesPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  const org = ctx.orgs.find((o) => o.slug === slug);
  if (!org) redirect("/new");

  const supabase = await v2ServerClient();

  // Respect the Articles feature toggle (redirect if it's off for this viewer).
  const isAdmin = org.role === "owner" || org.role === "admin";
  const resolved = await loadResolvedFeatures(supabase, org.id, null);
  if (!isFeatureVisible(resolved, "articles", isAdmin)) redirect(`/new/${slug}`);

  const nowIso = new Date().toISOString();
  const { data } = await supabase
    .from("v2_articles")
    .select(
      "id, title, content, image_url, image_focal_x, image_focal_y, publish_at, author:v2_profiles(display_name, first_name, last_name, avatar_url)",
    )
    .eq("org_id", org.id)
    .not("publish_at", "is", null)
    .lte("publish_at", nowIso)
    .order("pinned_at", { ascending: false, nullsFirst: false })
    .order("publish_at", { ascending: false });

  const articles = ((data as unknown as ArticleRow[] | null) ?? []).map((a) => {
    const author = Array.isArray(a.author) ? a.author[0] ?? null : a.author;
    return {
      id: a.id,
      title: a.title,
      imageUrl: a.image_url,
      focalX: a.image_focal_x ?? 50,
      focalY: a.image_focal_y ?? 50,
      preview: stripMarkdown(a.content || "") || null,
      dateText: new Date(a.publish_at).toLocaleDateString("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric",
      }),
      authorName: author ? pickName(author, org.name_display) : null,
      authorAvatar: author?.avatar_url ?? null,
    };
  });

  return (
    <div className={`${styles.page} ${styles.orgPage}`}>
      <Link href={`/new/${slug}`} className={styles.back}>
        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
        </svg>
        Back
      </Link>

      <p className={styles.eyebrow}>Stories & Recognition</p>
      <h1 className={styles.title}>Articles</h1>

      {articles.length === 0 ? (
        <p className={styles.lede}>No articles published yet. Check back soon.</p>
      ) : (
        <div className={styles.articleList}>
          {articles.map((a) => (
            <Link key={a.id} href={`/new/${slug}/articles/${a.id}`} className={styles.articleCard}>
              <div className={styles.articleImage}>
                {a.imageUrl && (
                  <img src={a.imageUrl} alt="" style={{ objectPosition: `${a.focalX}% ${a.focalY}%` }} />
                )}
                <div className={styles.articleImageScrim} />
                <div className={styles.articleImageText}>
                  <p className={styles.articleOverlayTitle}>{a.title}</p>
                  <div className={styles.articleMeta}>
                    <span className={styles.articleDate}>{a.dateText}</span>
                    {a.authorName && (
                      <span className={styles.articleAuthorGroup}>
                        {a.authorAvatar ? (
                          <img className={styles.articleMetaAvatar} src={a.authorAvatar} alt="" />
                        ) : (
                          <span className={styles.articleMetaAvatarFallback}>
                            {a.authorName[0]?.toUpperCase() || "?"}
                          </span>
                        )}
                        <span className={styles.articleMetaAuthor}>{a.authorName}</span>
                      </span>
                    )}
                  </div>
                </div>
              </div>
              {a.preview && (
                <div className={styles.articleExcerptWrap}>
                  <p className={styles.articleExcerpt}>{a.preview}</p>
                </div>
              )}
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

import { redirect, notFound } from "next/navigation";
import Link from "next/link";
import ReactMarkdown from "react-markdown";
import { v2ServerClient } from "@/lib/v2/supabase";
import { getPlatformContext } from "@/lib/v2/context";
import { pickName } from "@/lib/v2/profile";
import { loadResolvedFeatures } from "@/lib/v2/features-server";
import { isFeatureVisible } from "@/lib/v2/features";
import ArticleViewPing from "../ArticleViewPing";
import styles from "@/app/new/new.module.css";
/* eslint-disable @next/next/no-img-element */

interface AuthorRef {
  display_name: string;
  first_name: string | null;
  last_name: string | null;
  avatar_url: string | null;
}
interface ArticleRow {
  id: string;
  title: string;
  content: string;
  image_url: string | null;
  image_focal_x: number | null;
  image_focal_y: number | null;
  publish_at: string | null;
  author: AuthorRef | AuthorRef[] | null;
}

/**
 * Full article reading page. Reached by tapping the featured-article card on the
 * home page. RLS scopes reads to published org articles (admins can preview
 * drafts). Author name honors the org's name-display mode.
 */
export default async function ArticlePage({
  params,
}: {
  params: Promise<{ slug: string; articleId: string }>;
}) {
  const { slug, articleId } = await params;
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  const org = ctx.orgs.find((o) => o.slug === slug);
  if (!org) redirect("/new");

  const supabase = await v2ServerClient();

  // Respect the Articles feature toggle (redirect if it's off for this viewer).
  const isAdmin = org.role === "owner" || org.role === "admin";
  const resolved = await loadResolvedFeatures(supabase, org.id, null);
  if (!isFeatureVisible(resolved, "articles", isAdmin)) redirect(`/new/${slug}`);

  const { data } = await supabase
    .from("v2_articles")
    .select(
      "id, title, content, image_url, image_focal_x, image_focal_y, publish_at, author:v2_profiles(display_name, first_name, last_name, avatar_url)",
    )
    .eq("id", articleId)
    .eq("org_id", org.id)
    .maybeSingle();
  if (!data) notFound();

  const a = data as unknown as ArticleRow;
  const author = Array.isArray(a.author) ? a.author[0] ?? null : a.author;
  const authorName = author ? pickName(author, org.name_display) : null;
  const dateText = a.publish_at
    ? new Date(a.publish_at).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })
    : null;

  return (
    <div className={`${styles.page} ${styles.orgPage}`}>
      <Link href={`/new/${slug}/articles`} className={styles.back}>
        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
        </svg>
        Articles
      </Link>

      <article className={styles.articleDetail}>
        {a.image_url && (
          <div className={styles.articleDetailImage}>
            <img
              src={a.image_url}
              alt=""
              style={{ objectPosition: `${a.image_focal_x ?? 50}% ${a.image_focal_y ?? 50}%` }}
            />
          </div>
        )}

        <h1 className={styles.articleDetailTitle}>{a.title}</h1>

        <div className={styles.articleDetailByline}>
          {dateText && <span className={styles.articleBylineDate}>{dateText}</span>}
          {authorName && (
            <span className={styles.articleBylineAuthorGroup}>
              {author?.avatar_url ? (
                <img className={styles.articleBylineAvatar} src={author.avatar_url} alt="" />
              ) : (
                <span className={styles.articleBylineAvatarFallback}>{authorName[0]?.toUpperCase() || "?"}</span>
              )}
              <span className={styles.articleBylineAuthor}>{authorName}</span>
            </span>
          )}
        </div>

        <div className={styles.articleBody}>
          <ReactMarkdown
            components={{
              // ![alt](url) renders a <video> when the URL points at a video
              // file (article videos use the same markdown-image syntax as images).
              img: ({ src, alt }) =>
                typeof src === "string" && /\.(mp4|webm|mov)(\?|#|$)/i.test(src) ? (
                  <video src={src} controls playsInline preload="metadata" className={styles.articleBodyVideo} />
                ) : (
                  <img src={typeof src === "string" ? src : undefined} alt={alt || ""} />
                ),
            }}
          >
            {a.content}
          </ReactMarkdown>
          <ArticleViewPing articleId={a.id} />
        </div>
      </article>
    </div>
  );
}

