=== v1 RichTextEditor full ===
"use client";

import { useEditor, EditorContent } from "@tiptap/react";
import { Node, mergeAttributes } from "@tiptap/core";
import StarterKit from "@tiptap/starter-kit";
import Underline from "@tiptap/extension-underline";
import Link from "@tiptap/extension-link";
import Image from "@tiptap/extension-image";
import { Markdown } from "tiptap-markdown";
import { useEffect, useCallback, useState } from "react";
import { ArticleImageDrawer } from "./ArticleImageDrawer";
import { BTN_NEUTRAL } from "@/lib/ui/buttons";

const SIZE_PRESETS: { label: string; value: string | null }[] = [
  { label: "Small", value: "33%" },
  { label: "Medium", value: "66%" },
  { label: "Full", value: null },
];

// Image extension with a `width` attribute that round-trips through markdown.
// When width is set, the image serializes as inline HTML so the `style` survives;
// when null, it falls back to the standard `![alt](src)` markdown output.
// Native Tiptap nodes don't include video. Without an explicit Node, raw
// <video> HTML from the Markdown extension gets escaped and shown as
// text in the editor. This node registers the schema so videos render
// as a real player while authoring AND survive markdown round-trips.
const VideoNode = Node.create({
  name: "video",
  group: "block",
  atom: true,
  draggable: true,
  selectable: true,
  addAttributes() {
    return {
      src: { default: null },
      controls: { default: true },
      playsinline: { default: true },
      preload: { default: "metadata" },
      style: { default: "width:100%" },
    };
  },
  parseHTML() {
    return [{ tag: "video[src]" }];
  },
  renderHTML({ HTMLAttributes }) {
    return ["video", mergeAttributes(HTMLAttributes)];
  },
  addStorage() {
    return {
      markdown: {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        serialize(state: any, node: any) {
          const src: string | null = node.attrs.src;
          if (!src) return;
          const escSrc = src.replace(/"/g, "&quot;");
          state.write(
            `<video src="${escSrc}" controls playsinline preload="metadata" style="width:100%"></video>`,
          );
          state.closeBlock(node);
        },
        parse: {},
      },
    };
  },
});

const ResizableImage = Image.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      width: {
        default: null as string | null,
        parseHTML: (el) => {
          const style = (el as HTMLElement).getAttribute("style") || "";
          const m = style.match(/width:\s*([^;]+)/i);
          if (m) return m[1].trim();
          return (el as HTMLElement).getAttribute("width") || null;
        },
        renderHTML: (attrs: { width?: string | null }) => {
          if (!attrs.width) return {};
          return { style: `width: ${attrs.width}` };
        },
      },
    };
  },
  addStorage() {
    const parent = this.parent?.() ?? {};
    return {
      ...parent,
      markdown: {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        serialize(state: any, node: any) {
          const src: string | null = node.attrs.src;
          const alt: string = node.attrs.alt || "";
          const width: string | null = node.attrs.width;
          if (!src) return;
          if (width) {
            const escAlt = alt.replace(/"/g, "&quot;");
            const escSrc = src.replace(/"/g, "&quot;");
            state.write(
              `<img src="${escSrc}" alt="${escAlt}" style="width: ${width}">`
            );
          } else {
            const altText = alt.replace(/[\[\]]/g, "");
            state.write(`![${altText}](${src})`);
          }
        },
        parse: {},
      },
    };
  },
});

interface RichTextEditorProps {
  content: string; // markdown
  onChange: (markdown: string) => void;
}

export function RichTextEditor({ content, onChange }: RichTextEditorProps) {
  const [linkUrl, setLinkUrl] = useState("");
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [showImagePicker, setShowImagePicker] = useState(false);
  const [imageSelected, setImageSelected] = useState(false);
  const [imageWidth, setImageWidth] = useState<string | null>(null);

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: { levels: [2, 3] },
      }),
      Underline,
      Link.configure({
        openOnClick: false,
        HTMLAttributes: { class: "text-green-700 underline font-medium" },
      }),
      ResizableImage.configure({
        HTMLAttributes: { class: "rounded-xl max-w-full" },
      }),
      VideoNode.configure({
        HTMLAttributes: { class: "rounded-xl max-w-full" },
      }),
      Markdown.configure({
        html: true,
        transformPastedText: true,
        transformCopiedText: true,
      }),
    ],
    content,
    editorProps: {
      attributes: {
        class: "prose prose-sm max-w-none p-3 min-h-[200px] text-gray-700 focus:outline-none",
      },
    },
    immediatelyRender: false,
    onUpdate: ({ editor }) => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const md = (editor.storage as any).markdown.getMarkdown();
      onChange(md);
    },
  });

  // Sync content when it changes externally (e.g., loading a different article)
  useEffect(() => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    if (editor && content !== (editor.storage as any).markdown.getMarkdown()) {
      editor.commands.setContent(content);
    }
  }, [content, editor]);

  // Track whether an image is selected so we can show the size bar.
  useEffect(() => {
    if (!editor) return;
    const update = () => {
      const active = editor.isActive("image");
      setImageSelected(active);
      setImageWidth(
        active ? (editor.getAttributes("image").width as string | null) ?? null : null
      );
    };
    update();
    editor.on("selectionUpdate", update);
    editor.on("transaction", update);
    return () => {
      editor.off("selectionUpdate", update);
      editor.off("transaction", update);
    };
  }, [editor]);

  const setImageSize = useCallback(
    (width: string | null) => {
      if (!editor) return;
      editor.chain().focus().updateAttributes("image", { width }).run();
    },
    [editor]
  );

  const addLink = useCallback(() => {
    if (!editor || !linkUrl) return;
    editor
      .chain()
      .focus()
      .extendMarkRange("link")
      .setLink({ href: linkUrl })
      .run();
    setLinkUrl("");
    setShowLinkInput(false);
  }, [editor, linkUrl]);

  if (!editor) return null;

  return (
    <div>
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-1 px-2 py-1.5 bg-gray-50 border border-gray-300 border-b-0 rounded-t-xl">
        <ToolbarButton
          onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
          active={editor.isActive("heading", { level: 2 })}
          title="Header"
        >
          H1
        </ToolbarButton>
        <ToolbarButton
          onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
          active={editor.isActive("heading", { level: 3 })}
          title="Subheader"
        >
          H2
        </ToolbarButton>
        <Divider />
        <ToolbarButton
          onClick={() => editor.chain().focus().toggleBold().run()}
          active={editor.isActive("bold")}
          title="Bold"
        >
          <span className="font-bold">B</span>
        </ToolbarButton>
        <ToolbarButton
          onClick={() => editor.chain().focus().toggleItalic().run()}
          active={editor.isActive("italic")}
          title="Italics"
        >
          <span className="italic">I</span>
        </ToolbarButton>
        <ToolbarButton
          onClick={() => editor.chain().focus().toggleUnderline().run()}
          active={editor.isActive("underline")}
          title="Underline"
        >
          <span className="underline">U</span>
        </ToolbarButton>
        <Divider />
        <ToolbarButton
          onClick={() => {
            if (editor.isActive("link")) {
              editor.chain().focus().unsetLink().run();
            } else {
              const existingHref = editor.getAttributes("link").href;
              setLinkUrl(existingHref || "https://");
              setShowLinkInput(true);
            }
          }}
          active={editor.isActive("link")}
          title="Link"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" />
          </svg>
        </ToolbarButton>
        <ToolbarButton
          onClick={() => setShowImagePicker(true)}
          title="Insert Image"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
        </ToolbarButton>
        <ToolbarButton
          onClick={() => editor.chain().focus().toggleBulletList().run()}
          active={editor.isActive("bulletList")}
          title="Bulleted List"
        >
          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
            <circle cx="4" cy="6" r="1.5" />
