43	
44	    const isVideo = file.type.startsWith("video/");
45	    const isImage = file.type.startsWith("image/");
46	
47	    setUploading(true);
48	    setUploadStatus(isVideo ? "Compressing video..." : "Uploading...");
49	    try {
50	      // Client-side compression keeps article media small and prevents
51	      // hitting the upload route's size cap. compressImage and
52	      // compressVideo both fall through their no-op paths when the
53	      // input is already smaller than the target.
54	      let blob: Blob = file;
55	      let uploadName = file.name;
56	      if (isImage) {
