126	 * Hole / Par / Hcp header plus every player's hole-by-hole scores; the viewer's
127	 * row is subtly highlighted. Lazy-fetches on first expand.
128	 */
129	export default function RoundDetail({
130	  id,
131	  orgId,
132	  viewerId,
133	  onResume,
134	  onDeleted,
135	  defaultCommentsOpen = false,
136	}: {
137	  id: string;
138	  orgId: string;
139	  viewerId: string;
140	  onResume?: () => void;
141	  onDeleted?: () => void;
142	  defaultCommentsOpen?: boolean;
143	}) {
144	  const [loaded, setLoaded] = useState(false);
145	  const [d, setD] = useState<Detail | null>(null);
146	  const [confirmOpen, setConfirmOpen] = useState(false);
147	  const [deleting, setDeleting] = useState(false);
148	  const [commentsOpen, setCommentsOpen] = useState(defaultCommentsOpen);
149	  const mode = useNameMode();
150	
151	  async function handleDelete() {
152	    setDeleting(true);
153	    try {
154	      const res = await fetch(`/api/v2/rounds/${id}`, { method: "DELETE" });
155	      if (res.ok) {
156	        setConfirmOpen(false);
