toolUseResult.originalFile:
import React from "react";

/**
 * Group scorecard rendered for next/og `ImageResponse` (#204). One row per player
 * (guests included for context), a shared par row, per-hole color coding
 * (birdie/eagle circled green, bogey+ boxed amber/red), putts as a superscript,
 * and the sharer's row highlighted. Satori is flexbox-only, so the table is built
 * from flex rows/cells — no CSS grid.
 */

export interface CardCell {
  strokes: number | null;
  putts: number | null;
}
export interface CardPlayer {
  name: string;
  highlight: boolean;
  total: number | null;
  toPar: number | null;
  cells: CardCell[]; // aligned to holes order
}
export interface ScorecardData {
  orgName: string;
  logoUrl: string | null;
  accent: string;
  courseName: string;
  subtitle: string;
  holes: { hole_number: number; par: number }[];
  parTotal: number;
  players: CardPlayer[];
}

const INK = "#14241b";
const MUTED = "#6b7280";
const LINE = "#e5e7eb";

const NAME_W = 190;
const CELL_W = 54;
const TOT_W = 92;
const ROW_H = 50;
const HEADER_H = 132;
const PAD = 40;

/** Pixel dimensions for a card — used by both the element and ImageResponse. */
export function scorecardSize(holesLen: number, playersLen: number): { width: number; height: number } {
  return {
    width: PAD * 2 + NAME_W + holesLen * CELL_W + TOT_W,
    height: PAD * 2 + HEADER_H + ROW_H * (playersLen + 1),
  };
}

function toParText(toPar: number | null): string {
  if (toPar == null) return "—";
  if (toPar === 0) return "E";
  return toPar > 0 ? `+${toPar}` : `${toPar}`;
}

/** Color + shape for a score cell relative to par. */
function scoreStyle(diff: number): { bg: string; color: string; radius: number } {
  if (diff <= -2) return { bg: "#bbf7d0", color: "#166534", radius: 999 }; // eagle+
  if (diff === -1) return { bg: "#dcfce7", color: "#15803d", radius: 999 }; // birdie
  if (diff === 0) return { bg: "transparent", color: INK, radius: 8 }; // par
  if (diff === 1) return { bg: "#fef3c7", color: "#b45309", radius: 8 }; // bogey
  return { bg: "#fee2e2", color: "#dc2626", radius: 8 }; // double+
}

function Cell({ cell, par }: { cell: CardCell; par: number }) {
  const base: React.CSSProperties = {
    width: CELL_W,
    height: ROW_H,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    borderLeft: `1px solid ${LINE}`,
  };
  if (cell.strokes == null) return <div style={base} />;
  const s = scoreStyle(cell.strokes - par);
  return (
    <div style={base}>
      <div
        style={{
          position: "relative",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          width: 36,
          height: 36,
          background: s.bg,
          borderRadius: s.radius,
        }}
      >
        <span style={{ fontSize: 22, fontWeight: 700, color: s.color }}>{cell.strokes}</span>
        {cell.putts != null && (
          <span style={{ position: "absolute", top: -6, right: -8, fontSize: 12, color: MUTED }}>{cell.putts}</span>
        )}
      </div>
    </div>
  );
}

export function ScorecardImage(d: ScorecardData): React.ReactElement {
  const { width, height } = scorecardSize(d.holes.length, d.players.length);

  const headCell = (label: string, w: number, extra?: React.CSSProperties): React.ReactElement => (
    <div
      style={{
        width: w,
        height: ROW_H,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: MUTED,
        fontSize: 15,
        fontWeight: 700,
        borderLeft: `1px solid ${LINE}`,
        ...extra,
      }}
    >
      {label}
    </div>
  );

  return (
    <div
      style={{
        width,
        height,
        display: "flex",
        flexDirection: "column",
        background: "#ffffff",
        padding: PAD,
        fontFamily: "sans-serif",
      }}
    >
      {/* Header */}
      <div style={{ height: HEADER_H, display: "flex", alignItems: "center" }}>
        {d.logoUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={d.logoUrl} width={72} height={72} style={{ objectFit: "contain", marginRight: 20 }} alt="" />
        )}
        <div style={{ display: "flex", flexDirection: "column" }}>
          <span style={{ fontSize: 22, fontWeight: 700, color: d.accent, letterSpacing: 1 }}>
            {d.orgName.toUpperCase()}
          </span>
          <span style={{ fontSize: 40, fontWeight: 800, color: INK, marginTop: 2 }}>{d.courseName}</span>
          <span style={{ fontSize: 20, color: MUTED, marginTop: 4 }}>{d.subtitle}</span>
        </div>
      </div>

      {/* Header row: Player | holes | Tot */}
      <div style={{ display: "flex", borderTop: `2px solid ${INK}`, borderBottom: `1px solid ${LINE}` }}>
        <div
          style={{
            width: NAME_W,
            height: ROW_H,
            display: "flex",
            alignItems: "center",
            paddingLeft: 6,
            color: MUTED,
            fontSize: 15,
            fontWeight: 700,
          }}
        >
          Player
        </div>
        {d.holes.map((h) => headCell(String(h.hole_number), CELL_W))}
        {headCell("Tot", TOT_W)}
      </div>

      {/* Par row */}
      <div style={{ display: "flex", background: "#f8faf9", borderBottom: `2px solid ${INK}` }}>
        <div
          style={{
            width: NAME_W,
            height: ROW_H,
            display: "flex",
            alignItems: "center",
            paddingLeft: 6,
            color: INK,
            fontSize: 16,
            fontWeight: 700,
          }}
        >
          Par
        </div>
        {d.holes.map((h) =>
          headCell(String(h.par), CELL_W, { color: INK, fontWeight: 600 }),
        )}
        {headCell(String(d.parTotal), TOT_W, { color: INK })}
      </div>

      {/* Player rows */}
      {d.players.map((p, i) => (
        <div
          key={i}
          style={{
            display: "flex",
            borderBottom: `1px solid ${LINE}`,
            background: p.highlight ? `${d.accent}14` : "transparent",
          }}
        >
          <div
            style={{
              width: NAME_W,
              height: ROW_H,
              display: "flex",
              alignItems: "center",
              paddingLeft: 6,
              color: INK,
              fontSize: 18,
              fontWeight: p.highlight ? 800 : 600,
              overflow: "hidden",
            }}
          >
            {p.name}
          </div>
          {p.cells.map((c, j) => (
            <Cell key={j} cell={c} par={d.holes[j]?.par ?? 4} />
          ))}
          <div
            style={{
              width: TOT_W,
              height: ROW_H,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              borderLeft: `1px solid ${LINE}`,
            }}
          >
            <span style={{ fontSize: 22, fontWeight: 800, color: INK }}>{p.total ?? "—"}</span>
            <span style={{ fontSize: 13, color: MUTED, marginTop: -2 }}>{toParText(p.toPar)}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

