const INK = "#14241b";
const MUTED = "#6b7280";
const LINE = "#e5e7eb";

const NAME_W = 190;
const CELL_W = 54;
const TOT_W = 92;
const ROW_H = 50;
const HEADER_H = 132;
const PAD = 40;

/** Pixel dimensions for a card — used by both the element and ImageResponse.
 *  Rows below the header: column-header + par + one per player = playersLen + 2. */
export function scorecardSize(holesLen: number, playersLen: number): { width: number; height: number } {
  return {
    width: PAD * 2 + NAME_W + holesLen * CELL_W + TOT_W,
    height: PAD * 2 + HEADER_H + ROW_H * (playersLen + 2),
  };
}

function toParText(toPar: number | null): string {
  if (toPar == null) return "—";
  if (toPar === 0) return "E";
  return toPar > 0 ? `+${toPar}` : `${toPar}`;
}

/** Classic scorecard notation: circle = under par, square = over; doubled for
 *  eagle+ / double-bogey+. Par is a plain number. */
function shapeFor(diff: number): { kind: "none" | "circle" | "square"; double: boolean } {
  if (diff <= -2) return { kind: "circle", double: true }; // eagle or better
  if (diff === -1) return { kind: "circle", double: false }; // birdie
  if (diff === 0) return { kind: "none", double: false }; // par
  if (diff === 1) return { kind: "square", double: false }; // bogey
  return { kind: "square", double: true }; // double bogey or worse
}

function Shape({ kind, double, children }: { kind: "circle" | "square"; double: boolean; children: React.ReactNode }) {
  const radius = kind === "circle" ? 999 : 6;
  const inner = (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: 34,
        height: 34,
        border: `2px solid ${INK}`,
        borderRadius: radius,
      }}
    >
      {children}
    </div>
  );
  if (!double) return inner;
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: 42,
        height: 42,
        border: `2px solid ${INK}`,
        borderRadius: radius,
      }}
    >
      {inner}
    </div>
  );
}

function Cell({ cell, par }: { cell: CardCell; par: number }) {
  const base: React.CSSProperties = {
    position: "relative",
    width: CELL_W,
    height: ROW_H,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    borderLeft: `1px solid ${LINE}`,
  };
  if (cell.strokes == null) return <div style={base} />;
  const num = <span style={{ fontSize: 22, fontWeight: 700, color: INK }}>{cell.strokes}</span>;
  const { kind, double } = shapeFor(cell.strokes - par);
  return (
    <div style={base}>
      {kind === "none" ? (
        num
      ) : (
        <Shape kind={kind} double={double}>
          {num}
        </Shape>
      )}
      {cell.putts != null && (
        <span style={{ position: "absolute", top: 3, right: 6, fontSize: 12, color: MUTED }}>{cell.putts}</span>
      )}
    </div>
  );
}

