import React from "react";

/**
 * Group scorecard rendered for next/og `ImageResponse` (#204). One row per player
 * (guests included for context), a shared par row, per-hole color coding
 * (birdie/eagle circled green, bogey+ boxed amber/red), putts as a superscript,
 * and the sharer's row highlighted. Satori is flexbox-only, so the table is built
 * from flex rows/cells — no CSS grid.
 */

export interface CardCell {
  strokes: number | null;
  putts: number | null;
}
export interface CardPlayer {
  name: string;
  total: number | null;
  toPar: number | null;
  cells: CardCell[]; // aligned to holes order
}
export interface ScorecardData {
  orgName: string;
  logoUrl: string | null;
  accent: string;
  courseName: string;
  subtitle: string;
  holes: { hole_number: number; par: number }[];
  parTotal: number;
  players: CardPlayer[];
}

const INK = "#14241b";
const MUTED = "#6b7280";
const LINE = "#e5e7eb";

const NAME_W = 190;
const CELL_W = 54;
const TOT_W = 92;
const ROW_H = 50;
const HEADER_H = 132;
const PAD = 40;

/** Pixel dimensions for a card — used by both the element and ImageResponse.
 *  Rows below the header: column-header + par + one per player = playersLen + 2. */
export function scorecardSize(holesLen: number, playersLen: number): { width: number; height: number } {
  return {
    width: PAD * 2 + NAME_W + holesLen * CELL_W + TOT_W,
    // + buffer so cumulative row borders never clip the final row.
    height: PAD * 2 + HEADER_H + ROW_H * (playersLen + 2) + 16,
  };
}

function toParText(toPar: number | null): string {
  if (toPar == null) return "—";
  if (toPar === 0) return "E";
  return toPar > 0 ? `+${toPar}` : `${toPar}`;
}

/** Classic scorecard notation: circle = under par, square = over; doubled for
 *  eagle+ / double-bogey+. Par is a plain number. */
function shapeFor(diff: number): { kind: "none" | "circle" | "square"; double: boolean } {
  if (diff <= -2) return { kind: "circle", double: true }; // eagle or better
  if (diff === -1) return { kind: "circle", double: false }; // birdie
  if (diff === 0) return { kind: "none", double: false }; // par
  if (diff === 1) return { kind: "square", double: false }; // bogey
  return { kind: "square", double: true }; // double bogey or worse
}

function Shape({ kind, double, children }: { kind: "circle" | "square"; double: boolean; children: React.ReactNode }) {
  const radius = kind === "circle" ? 999 : 6;
  const inner = (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: 34,
        height: 34,
        border: `2px solid ${INK}`,
        borderRadius: radius,
      }}
    >
      {children}
    </div>
  );
  if (!double) return inner;
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: 42,
        height: 42,
        border: `2px solid ${INK}`,
        borderRadius: radius,
      }}
    >
      {inner}
    </div>
  );
}

function Cell({ cell, par }: { cell: CardCell; par: number }) {
  const base: React.CSSProperties = {
    position: "relative",
    width: CELL_W,
    height: ROW_H,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    borderLeft: `1px solid ${LINE}`,
  };
  if (cell.strokes == null) return <div style={base} />;
  const num = <span style={{ fontSize: 22, fontWeight: 700, color: INK }}>{cell.strokes}</span>;
  const { kind, double } = shapeFor(cell.strokes - par);
  return (
    <div style={base}>
      {kind === "none" ? (
        num
      ) : (
        <Shape kind={kind} double={double}>
          {num}
        </Shape>
      )}
      {cell.putts != null && (
        <span style={{ position: "absolute", top: 3, right: 6, fontSize: 12, color: MUTED }}>{cell.putts}</span>
      )}
    </div>
  );
}

export function ScorecardImage(d: ScorecardData): React.ReactElement {
  const { width, height } = scorecardSize(d.holes.length, d.players.length);

  const headCell = (label: string, w: number, extra?: React.CSSProperties): React.ReactElement => (
    <div
      style={{
        width: w,
        height: ROW_H,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: MUTED,
        fontSize: 15,
        fontWeight: 700,
        borderLeft: `1px solid ${LINE}`,
        ...extra,
      }}
    >
      {label}
    </div>
  );

  return (
    <div
      style={{
        width,
        height,
        display: "flex",
        flexDirection: "column",
        background: "#ffffff",
        padding: PAD,
        fontFamily: "sans-serif",
      }}
    >
      {/* Header */}
      <div style={{ height: HEADER_H, display: "flex", alignItems: "center" }}>
        {d.logoUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={d.logoUrl} width={72} height={72} style={{ objectFit: "contain", marginRight: 20 }} alt="" />
        )}
        <div style={{ display: "flex", flexDirection: "column" }}>
          <span style={{ fontSize: 22, fontWeight: 700, color: d.accent, letterSpacing: 1 }}>
            {d.orgName.toUpperCase()}
          </span>
          <span style={{ fontSize: 40, fontWeight: 800, color: INK, marginTop: 2 }}>{d.courseName}</span>
          <span style={{ fontSize: 20, color: MUTED, marginTop: 4 }}>{d.subtitle}</span>
        </div>
      </div>

      {/* Header row: Player | holes | Tot */}
      <div style={{ display: "flex", borderTop: `2px solid ${INK}`, borderBottom: `1px solid ${LINE}` }}>
        <div
          style={{
            width: NAME_W,
            height: ROW_H,
            display: "flex",
            alignItems: "center",
            paddingLeft: 6,
            color: MUTED,
            fontSize: 15,
            fontWeight: 700,
          }}
        >
          Player
        </div>
        {d.holes.map((h) => headCell(String(h.hole_number), CELL_W))}
        {headCell("Tot", TOT_W)}
      </div>

      {/* Par row */}
      <div style={{ display: "flex", background: "#f8faf9", borderBottom: `2px solid ${INK}` }}>
        <div
          style={{
            width: NAME_W,
            height: ROW_H,
            display: "flex",
            alignItems: "center",
            paddingLeft: 6,
            color: INK,
            fontSize: 16,
            fontWeight: 700,
          }}
        >
          Par
        </div>
        {d.holes.map((h) =>
          headCell(String(h.par), CELL_W, { color: INK, fontWeight: 600 }),
        )}
        {headCell(String(d.parTotal), TOT_W, { color: INK })}
      </div>

      {/* Player rows */}
      {d.players.map((p, i) => (
        <div key={i} style={{ display: "flex", borderBottom: `1px solid ${LINE}` }}>
          <div
            style={{
              width: NAME_W,
              height: ROW_H,
              display: "flex",
              alignItems: "center",
              paddingLeft: 6,
              color: INK,
              fontSize: 18,
              fontWeight: 600,
              overflow: "hidden",
            }}
          >
            {p.name}
          </div>
          {p.cells.map((c, j) => (
            <Cell key={j} cell={c} par={d.holes[j]?.par ?? 4} />
          ))}
          <div
            style={{
              width: TOT_W,
              height: ROW_H,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              borderLeft: `1px solid ${LINE}`,
            }}
          >
            <span style={{ fontSize: 22, fontWeight: 800, color: INK }}>{p.total ?? "—"}</span>
            <span style={{ fontSize: 13, color: MUTED, marginTop: -2 }}>{toParText(p.toPar)}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

import { ImageResponse } from "next/og";
import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { formatCourseName } from "@/lib/v2/course-display";
import { pickName, type NameMode } from "@/lib/v2/profile";
import { ScorecardImage, scorecardSize, type CardPlayer } from "@/lib/v2/rounds/scorecard-image";

/**
 * GET /api/v2/rounds/[id]/card.png — a shareable group scorecard PNG (#204),
 * rendered on demand (never persisted). Every player appears (guests included for
 * context); the requesting viewer's row is highlighted. Auth-gated — no MMS, so it
 * needn't be public.
 */
export const dynamic = "force-dynamic";

const one = <T,>(v: T | T[] | null | undefined): T | null => (Array.isArray(v) ? v[0] ?? null : v ?? null);

export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });

  const admin = v2AdminClient();
  const { data: round } = await admin
    .from("v2_rounds")
    .select(
      `id, org_id, round_date, round_type, format,
       course:v2_courses(name, club_name),
       tee:v2_course_tees(tee_name, par),
       players:v2_round_players(id, user_id, guest_name, tee_id, player_position, final_gross_score,
         profile:v2_profiles(display_name, first_name, last_name, nickname, avatar_url))`,
    )
    .eq("id", id)
    .order("player_position", { referencedTable: "players", ascending: true })
    .maybeSingle();
  if (!round) return NextResponse.json({ error: "Round not found" }, { status: 404 });

  const org = round.org_id
    ? one(
        (
          await admin
            .from("v2_organizations")
            .select("name, logo_url, primary_color, name_display")
            .eq("id", round.org_id)
            .maybeSingle()
        ).data,
      )
    : null;
  const nameMode: NameMode = (org?.name_display as NameMode) || "nickname";

  const playerRows = round.players || [];
  const gridTeeId = (playerRows.find((p) => p.user_id === userId) ?? playerRows[0])?.tee_id ?? round.players?.[0]?.tee_id;

  const inNine = (h: number) =>
    round.round_type === "9-front" ? h <= 9 : round.round_type === "9-back" ? h >= 10 : true;

  const { data: holeRows } = gridTeeId
    ? await admin
        .from("v2_course_holes")
        .select("hole_number, par")
        .eq("tee_id", gridTeeId)
        .order("hole_number", { ascending: true })
    : { data: [] };
  const holes = (holeRows || []).filter((h) => inNine(h.hole_number)).map((h) => ({ hole_number: h.hole_number, par: h.par }));
  const parTotal = holes.reduce((s, h) => s + h.par, 0);

  const { data: scoreRows } = await admin
    .from("v2_round_scores")
    .select("round_player_id, hole_number, strokes, putts")
    .eq("round_id", id);
  const byPlayer = new Map<string, Map<number, { strokes: number | null; putts: number | null }>>();
  for (const s of scoreRows || []) {
    if (!inNine(s.hole_number)) continue;
    const m = byPlayer.get(s.round_player_id) || new Map();
    m.set(s.hole_number, { strokes: s.strokes ?? null, putts: s.putts ?? null });
    byPlayer.set(s.round_player_id, m);
  }

  const isScramble = round.format === "scramble";

  const toRow = (p: (typeof playerRows)[number], name: string): CardPlayer => {
    const scores = byPlayer.get(p.id) || new Map();
    const cells = holes.map((h) => scores.get(h.hole_number) || { strokes: null, putts: null });
    const summed = cells.reduce((s, c) => (c.strokes != null ? s + c.strokes : s), 0);
    const total = p.final_gross_score ?? (summed > 0 ? summed : null);
    return { name, total, toPar: total != null ? total - parTotal : null, cells };
  };

  const players: CardPlayer[] = isScramble
    ? playerRows[0]
      ? [toRow(playerRows[0], "Team")]
      : []
    : playerRows.map((p) => {
        const prof = one(p.profile);
        const name = p.user_id ? (prof ? pickName(prof, nameMode) : "Player") : `${p.guest_name || "Guest"}`;
        return toRow(p, name);
      });

  const course = one(round.course);
  const tee = one(round.tee);
  const holesLabel = round.round_type === "18" ? "18 holes" : round.round_type === "9-front" ? "Front 9" : "Back 9";
  const [y, m, dd] = (round.round_date || "").split("-").map(Number);
  const dateText = y ? new Date(y, (m || 1) - 1, dd || 1).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "";
  const subtitle = [tee?.tee_name ? `${tee.tee_name} tees` : null, holesLabel, dateText].filter(Boolean).join(" — ");

  const { width, height } = scorecardSize(holes.length, players.length);

  return new ImageResponse(
    ScorecardImage({
      orgName: org?.name || "Golf",
      logoUrl: org?.logo_url ?? null,
      accent: org?.primary_color || "#15803d",
      courseName: course ? formatCourseName(course) : "Round",
      subtitle,
      holes,
      parTotal,
      players,
    }),
    { width, height, headers: { "Cache-Control": "private, max-age=300" } },
  );
}

