          <TextCell value={totalYards || ""} w={TOT_W} h={INFO_H} style={summary({ color: MUTED, fontSize: 13, fontWeight: 600 })} />
        </div>
      )}

      {/* Par */}
      <div style={{ display: "flex", background: "#f8faf9", borderBottom: `1px solid ${LINE}` }}>
        <RowLabel value="Par" h={ROW_H} style={{ color: INK, fontSize: 16, fontWeight: 700 }} />
