}
export interface ScorecardData {
  orgName: string;
  logoUrl: string | null;
  accent: string;
  courseName: string;
  subtitle: string;
  holes: { hole_number: number; par: number }[];
  parTotal: number;
  players: CardPlayer[];
}

const INK = "#14241b";
const MUTED = "#6b7280";
const LINE = "#e5e7eb";
const STRIPE = "#f6f8f7"; // zebra row
const SUMMARY_BG = "#eef2f0"; // Out / In / Tot columns
const UNDER = "#15803d"; // under par
const OVER = "#b4472a"; // over par

const NAME_W = 224;
const CELL_W = 54;
const SUB_W = 62; // Out / In
const TOT_W = 88;
const ROW_H = 54;
const HEADER_H = 132;
const PAD = 40;

function hasBothNines(holes: { hole_number: number }[]): boolean {
  return holes.some((h) => h.hole_number <= 9) && holes.some((h) => h.hole_number >= 10);
}

/** Pixel dimensions — used by both the element and ImageResponse. */
export function scorecardSize(holes: { hole_number: number }[], playersLen: number): { width: number; height: number } {
  const subCols = hasBothNines(holes) ? 2 : 0;
  return {
    width: PAD * 2 + NAME_W + holes.length * CELL_W + subCols * SUB_W + TOT_W,
    // Rows below header: column-header + par + one per player (+ buffer for borders).
    height: PAD * 2 + HEADER_H + ROW_H * (playersLen + 2) + 16,
  };
}

function toParText(toPar: number | null): string {
  if (toPar == null) return "—";
  if (toPar === 0) return "E";
  return toPar > 0 ? `+${toPar}` : `−${Math.abs(toPar)}`;
}

/** Classic notation relative to par. */
function shapeFor(diff: number): { kind: "none" | "circle" | "square"; double: boolean } {
  if (diff <= -2) return { kind: "circle", double: true };
  if (diff === -1) return { kind: "circle", double: false };
  if (diff === 0) return { kind: "none", double: false };
  if (diff === 1) return { kind: "square", double: false };
  return { kind: "square", double: true };
}

// lineHeight:1 + a hair of translateY optically centers the glyph inside a shape
// (flexbox centers the line box, not the digit).
const NUM_STYLE: React.CSSProperties = {
  fontSize: 22,
  fontWeight: 700,
  color: INK,
  lineHeight: 1,
  display: "flex",
  transform: "translateY(0.75px)",
};

function ScoreCell({ cell, par }: { cell: CardCell; par: number }) {
  const base: React.CSSProperties = {
    position: "relative",
    width: CELL_W,
    height: ROW_H,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    borderLeft: `1px solid ${LINE}`,
  };
  if (cell.strokes == null) return <div style={base} />;
  const { kind, double } = shapeFor(cell.strokes - par);
  const num = <span style={NUM_STYLE}>{cell.strokes}</span>;

  let shape: React.ReactNode = num;
  if (kind !== "none") {
    const radius = kind === "circle" ? 999 : 6;
    const inner = (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 34, height: 34, border: `1.5px solid ${INK}`, borderRadius: radius }}>
        {num}
      </div>
    );
    shape = double ? (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 42, height: 42, border: `1.5px solid ${INK}`, borderRadius: radius }}>
        {inner}
      </div>
    ) : (
      inner
    );
  }

  return (
    <div style={base}>
      {shape}
      {/* Putt count sits INSIDE this cell's top-right and renders last (on top),
          so it's clearly tied to this hole and never hidden by the shape. */}
      {cell.putts != null && (
        <span style={{ position: "absolute", top: 3, right: 4, fontSize: 10, color: MUTED, lineHeight: 1 }}>{cell.putts}</span>
      )}
    </div>
  );
}

/** A subtotal / total cell (Out / In / Tot). */
function SumCell({ value, w, strong }: { value: number | string; w: number; strong?: boolean }) {
  return (
    <div
      style={{
        width: w,
        height: ROW_H,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        borderLeft: `1px solid ${LINE}`,
        background: SUMMARY_BG,
        color: INK,
        fontSize: strong ? 22 : 18,
        fontWeight: strong ? 800 : 600,
      }}
    >
      {value}
    </div>
  );
}

function headCell(label: string, w: number, extra?: React.CSSProperties): React.ReactElement {
  return (
    <div
      key={label + w + (extra ? "x" : "")}
      style={{
        width: w,
        height: ROW_H,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: MUTED,
        fontSize: 15,
        fontWeight: 700,
        lineHeight: 1,
        borderLeft: `1px solid ${LINE}`,
        ...extra,
      }}
    >
      {label}
    </div>
  );
}

function sum(cells: CardCell[]): number | null {
  const played = cells.filter((c) => c.strokes != null);
  if (played.length === 0) return null;
  return played.reduce((s, c) => s + (c.strokes ?? 0), 0);
}

export function ScorecardImage(d: ScorecardData): React.ReactElement {
  const { width, height } = scorecardSize(d.holes, d.players.length);
  const both = hasBothNines(d.holes);

  // Split holes (and each player's aligned cells) into front / back.
  const idx = d.holes.map((h, j) => ({ h, j }));
  const frontIdx = idx.filter((x) => x.h.hole_number <= 9);
  const backIdx = idx.filter((x) => x.h.hole_number >= 10);
  const frontPar = frontIdx.reduce((s, x) => s + x.h.par, 0);
  const backPar = backIdx.reduce((s, x) => s + x.h.par, 0);

  const nameCol = (label: string, extra?: React.CSSProperties) => (
    <div style={{ width: NAME_W, height: ROW_H, display: "flex", alignItems: "center", paddingLeft: 6, ...extra }}>{label}</div>
  );

  return (
    <div style={{ width, height, display: "flex", flexDirection: "column", background: "#ffffff", padding: PAD, fontFamily: "sans-serif" }}>
      {/* Header */}
      <div style={{ height: HEADER_H, display: "flex", alignItems: "center" }}>
        {d.logoUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={d.logoUrl} width={72} height={72} style={{ objectFit: "contain", marginRight: 20 }} alt="" />
        )}
        <div style={{ display: "flex", flexDirection: "column" }}>
          <span style={{ fontSize: 22, fontWeight: 700, color: d.accent, letterSpacing: 1 }}>{d.orgName.toUpperCase()}</span>
          <span style={{ fontSize: 40, fontWeight: 800, color: INK, marginTop: 2 }}>{d.courseName}</span>
          <span style={{ fontSize: 20, color: MUTED, marginTop: 4 }}>{d.subtitle}</span>
        </div>
      </div>

      {/* Column header */}
      <div style={{ display: "flex", borderTop: `2px solid ${INK}`, borderBottom: `1px solid ${LINE}` }}>
        {nameCol("Player", { color: MUTED, fontSize: 15, fontWeight: 700 })}
        {frontIdx.map((x) => headCell(String(x.h.hole_number), CELL_W))}
        {both && headCell("Out", SUB_W, { color: INK, background: SUMMARY_BG })}
        {backIdx.map((x) => headCell(String(x.h.hole_number), CELL_W))}
        {both && headCell("In", SUB_W, { color: INK, background: SUMMARY_BG })}
        {headCell("Tot", TOT_W, { color: INK, background: SUMMARY_BG })}
      </div>

      {/* Par row */}
      <div style={{ display: "flex", background: "#f8faf9", borderBottom: `2px solid ${INK}` }}>
        {nameCol("Par", { color: INK, fontSize: 16, fontWeight: 700 })}
        {frontIdx.map((x) => headCell(String(x.h.par), CELL_W, { color: INK, fontWeight: 600 }))}
        {both && <SumCell value={frontPar} w={SUB_W} />}
        {backIdx.map((x) => headCell(String(x.h.par), CELL_W, { color: INK, fontWeight: 600 }))}
        {both && <SumCell value={backPar} w={SUB_W} />}
        <SumCell value={d.parTotal} w={TOT_W} />
      </div>

      {/* Player rows */}
      {d.players.map((p, i) => {
        const frontCells = frontIdx.map((x) => p.cells[x.j] ?? { strokes: null, putts: null });
        const backCells = backIdx.map((x) => p.cells[x.j] ?? { strokes: null, putts: null });
        const outSum = sum(frontCells);
        const inSum = sum(backCells);
        const dpColor = p.toPar == null || p.toPar === 0 ? MUTED : p.toPar < 0 ? UNDER : OVER;
        return (
          <div key={i} style={{ display: "flex", borderBottom: `1px solid ${LINE}`, background: i % 2 === 1 ? STRIPE : "#ffffff" }}>
            <div style={{ width: NAME_W, height: ROW_H, display: "flex", alignItems: "center", paddingLeft: 6, overflow: "hidden" }}>
              <span style={{ color: INK, fontSize: 18, fontWeight: 600 }}>{p.name}</span>
              <span style={{ color: dpColor, fontSize: 15, fontWeight: 700, marginLeft: 8 }}>{toParText(p.toPar)}</span>
            </div>
            {frontCells.map((c, j) => (
              <ScoreCell key={`f${j}`} cell={c} par={frontIdx[j].h.par} />
            ))}
            {both && <SumCell value={outSum ?? "—"} w={SUB_W} />}
            {backCells.map((c, j) => (
              <ScoreCell key={`b${j}`} cell={c} par={backIdx[j].h.par} />
            ))}
            {both && <SumCell value={inSum ?? "—"} w={SUB_W} />}
            <SumCell value={p.total ?? "—"} w={TOT_W} strong />
          </div>
        );
      })}
    </div>
  );
}

