file.content:
.scMark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}
/* Two-digit hole scores (10+) grow the shape into an oval/rounded-rect but stay centered. */
.scMark[data-two] {
  width: auto;
  min-width: 20px;
  padding: 0 3px;
}
/* Optical vertical centering: digits sit ~1px high within their line box
   (ascender bias), so nudge the glyph — not the shape — down to sit dead-center. */
.scNum {
  display: block;
  line-height: 1;
  transform: translateY(0.75px);
}
.scMark[data-mark="birdie"] {
  border: 1.5px solid #16a34a;
  border-radius: 50%;
  color: #15803d;
}
.scMark[data-mark="eagle"] {
  border: 1.5px solid #16a34a;
  border-radius: 50%;
  color: #15803d;
  box-shadow: 0 0 0 2px var(--card), 0 0 0 3.5px #16a34a;
}
.scMark[data-mark="bogey"] {
  border: 1.5px solid var(--ink);
  border-radius: 4px;
}
.scMark[data-mark="double"] {
  border: 1.5px solid #b91c1c;
  border-radius: 4px;
  color: #b91c1c;
  box-shadow: 0 0 0 2px var(--card), 0 0 0 3.5px #b91c1c;
}
.scMark[data-mark="none"] {
  color: var(--line-strong);
  font-weight: 400;
}
.scTotalNum {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--ink);

