import { getTeeDotStyle } from "@/lib/utils/tee-colors";

function TeeDot({ color }: { color: string | null }) {
  const { className, style } = getTeeDotStyle(color);
  return <span className={`${styles.teeDot} ${className || ""}`} style={{ marginRight: 6, ...style }} />;
}

interface Hole {
  hole_number: number;
  par: number;
  handicap_index: number;
  yards: number | null;
}
interface PlayerStats {
  putts: number | null;
  fairways: { hit: number; of: number } | null;
  gir: { hit: number; of: number } | null;
  penalties: number | null;
}
interface PlayerRow {
  is_viewer: boolean;
  is_guest: boolean;
  guest_name: string | null;
  tee_color: string | null;
  profile: { display_name: string; first_name: string | null; last_name: string | null; nickname: string | null; avatar_url: string | null } | null;
  gross: number | null;
  to_par: number | null;
  scores: Record<number, number>;
  stats: PlayerStats;
}
interface Detail {
  id: string;
  status: "in_progress" | "completed" | "abandoned";
  round_type: "18" | "9-front" | "9-back";
  format: "individual" | "scramble";
  course_name: string;
  tee_name: string;
  tee_color: string | null;
  tee_gender: string | null;
  course_rating: number | null;
  slope_rating: number | null;
  gross: number | null;
  adjusted: number | null;
  differential: number | null;
  to_par: number | null;
  is_incomplete: boolean;
  holes_played: number;
  expected_holes: number;
  comment_count: number;
  can_manage: boolean;
  holes: Hole[];
  players: PlayerRow[];
}
interface LabeledPlayer extends PlayerRow {
  label: string;
}

function toParLabel(n: number): string {
  if (n === 0) return "E";
  return n > 0 ? `+${n}` : `−${Math.abs(n)}`;
}

/** Golf scorecard mark for a hole score relative to par. */
function mark(strokes: number | null, par: number): string {
  if (strokes == null) return "none";
  const d = strokes - par;
  if (d <= -2) return "eagle";
  if (d === -1) return "birdie";
  if (d === 0) return "par";
  if (d === 1) return "bogey";
  return "double";

