  const [commentsOpen, setCommentsOpen] = useState(defaultCommentsOpen);
  const mode = useNameMode();

  async function handleDelete() {
    setDeleting(true);
    try {
      const res = await fetch(`/api/v2/rounds/${id}`, { method: "DELETE" });
      if (res.ok) {
        setConfirmOpen(false);
        onDeleted?.();
      } else {
        setDeleting(false);
