1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import dynamic from "next/dynamic";
5	import Image from "next/image";
6	import { TEE_HEX_COLORS } from "@/lib/utils/tee-colors";
7	import type { HoleInfo } from "./ScoringShell";
8	
9	const HoleMapViewLazy = dynamic(() => import("@/components/my-rounds/HoleMapView"), {
10	  ssr: false,
11	  loading: () => (
12	    <div className="w-full h-full flex items-center justify-center bg-gray-100 text-gray-400 text-sm">
13	      Loading map…
14	    </div>
15	  ),
16	});
17	
18	type ImageView = "map" | "overhead" | "green";
19	
20	interface ScoringMapDrawerProps {
21	  holes: HoleInfo[];
22	  scorerHoleIndex: number;
23	  isOpen: boolean;
24	  onClose: () => void;
25	  isCompositionTee: boolean;
26	  roundTeeColor?: string | null;
27	  // Measured bottom edge (px) of the top nav chrome — the drawer starts here so
28	  // its close controls never tuck under the header (which may be taller than
29	  // 56px with the SimulatorBanner or a device safe-area). Falls back to 3.5rem.
30	  topOffset?: number | null;
31	  // Extra reserved space above the BottomNav (e.g., when the music mini-player
32	  // is showing). The drawer ends just above this strip so the strip stays
33	  // visible behind it.
34	  bottomReserved?: string;
35	}
36	
37	// Mounted continuously by ScoringShell so the Mapbox WebGL context warms up on
38	// page load. When `isOpen` is false the drawer slides off-screen but stays in
39	// the DOM, and its hole index follows the scorer's so that the first open lands
40	// on "now." While open, drawer-local chevrons drive the displayed hole via
41	// `override`; closing the drawer clears the override so the next reopen lands
42	// on the scorer's current hole again.
43	export function ScoringMapDrawer({
44	  holes,
45	  scorerHoleIndex,
46	  isOpen,
47	  onClose,
48	  isCompositionTee,
49	  roundTeeColor,
50	  topOffset = null,
51	  bottomReserved = "0px",
52	}: ScoringMapDrawerProps) {
53	  const [override, setOverride] = useState<number | null>(null);
54	  const drawerHoleIndex = override ?? scorerHoleIndex;
55	  const hole = holes[drawerHoleIndex] ?? holes[0];
56	
57	  function closeDrawer() {
58	    setOverride(null);
59	    onClose();
60	  }
61	
62	  // Restore the last view (Map / Overhead / Green) across reloads.
63	  const [imageView, setImageView] = useState<ImageView>(() => {
64	    if (typeof sessionStorage === "undefined") return "map";
65	    try {
66	      const raw = sessionStorage.getItem("scoring_image_view");
67	      return raw === "map" || raw === "overhead" || raw === "green" ? raw : "map";
68	    } catch {
69	      return "map";
70	    }
71	  });
72	  useEffect(() => {
73	    if (typeof sessionStorage === "undefined") return;
74	    try {
75	      sessionStorage.setItem("scoring_image_view", imageView);
76	    } catch {
77	      /* ignore */
78	    }
79	  }, [imageView]);
80	
81	  // Drag-to-collapse on the handle, matching MusicDrawer.
82	  const dragStartYRef = useRef<number | null>(null);
83	  const [dragOffset, setDragOffset] = useState(0);
84	
85	  function onHandleTouchStart(e: React.TouchEvent) {
86	    dragStartYRef.current = e.touches[0].clientY;
87	  }
88	  function onHandleTouchMove(e: React.TouchEvent) {
89	    if (dragStartYRef.current == null) return;
90	    const dy = e.touches[0].clientY - dragStartYRef.current;
91	    if (dy > 0) setDragOffset(dy);
92	  }
93	  function onHandleTouchEnd() {
94	    const start = dragStartYRef.current;
95	    dragStartYRef.current = null;
96	    const offset = dragOffset;
97	    setDragOffset(0);
98	    if (start != null && offset > 80) closeDrawer();
99	  }
100	
101	  // Lock background scroll while open.
102	  useEffect(() => {
103	    if (!isOpen) return;
104	    const prev = document.body.style.overflow;
105	    document.body.style.overflow = "hidden";
106	    return () => {
107	      document.body.style.overflow = prev;
108	    };
109	  }, [isOpen]);
110	
111	  const hasMap = hole?.tee_latitude != null && hole?.tee_longitude != null;
112	  const hasOverhead = !!hole?.overhead_image_url;
113	  const hasGreen = !!hole?.green_image_url;
114	  const availableViews = useMemo(
115	    () => [
116	      ...(hasMap ? [{ key: "map" as const, label: "Map" }] : []),
117	      ...(hasOverhead ? [{ key: "overhead" as const, label: "Overhead" }] : []),
118	      ...(hasGreen ? [{ key: "green" as const, label: "Green" }] : []),
119	    ],
120	    [hasMap, hasOverhead, hasGreen],
121	  );
122	  const activeView: ImageView | null =
123	    availableViews.find((v) => v.key === imageView)?.key || availableViews[0]?.key || null;
124	  const currentImageUrl =
125	    activeView === "overhead"
126	      ? hole?.overhead_image_url
127	      : activeView === "green"
128	        ? hole?.green_image_url
129	        : null;
130	
131	  if (!hole) return null;
132	
133	  const dotColor = isCompositionTee ? hole.source_tee_color || hole.tee_color : roundTeeColor;
134	  const dotHex = dotColor ? TEE_HEX_COLORS[dotColor] || null : null;
135	
136	  return (
137	    <div
138	      className={`fixed inset-x-0 z-[55] bg-white flex flex-col transition-transform duration-300 ease-out ${
139	        isOpen ? "translate-y-0" : "translate-y-full pointer-events-none"
140	      }`}
141	      style={{
142	        top: topOffset ?? "3.5rem",
143	        bottom: bottomReserved,
144	        transform: isOpen ? `translateY(${dragOffset}px)` : undefined,
145	        transition: dragOffset > 0 ? "none" : undefined,
146	      }}
147	      aria-hidden={!isOpen}
148	    >
149	      {/* Drag handle + explicit close button. The handle alone wasn't a
150	          discoverable way out (looked like decoration), so a labeled ✕ button
151	          sits at the top-right of this bar and is always tappable. The bar has
152	          its own height so the button never overlaps the hole-nav row below. */}
153	      <div
154	        className="shrink-0 relative flex items-center justify-center bg-white min-h-[2.75rem]"
155	        onTouchStart={onHandleTouchStart}
156	        onTouchMove={onHandleTouchMove}
157	        onTouchEnd={onHandleTouchEnd}
158	      >
159	        <button
160	          type="button"
161	          onClick={closeDrawer}
162	          aria-label="Close map"
163	          className="w-12 h-1.5 rounded-full bg-gray-300 active:bg-gray-400"
164	        />
165	        <button
166	          type="button"
167	          onClick={closeDrawer}
168	          aria-label="Close map"
169	          className="absolute right-2 top-1/2 -translate-y-1/2 inline-flex items-center gap-1 rounded-full bg-gray-900/85 text-white text-xs font-semibold pl-2 pr-2.5 py-1 shadow-lg active:bg-gray-900"
170	        >
171	          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
172	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
173	          </svg>
174	          Close
175	        </button>
176	      </div>
177	
178	      {/* Hole nav header */}
179	      <div className="flex items-center justify-between px-3 py-2 border-b border-gray-100 bg-white shrink-0">
180	        <button
181	          type="button"
182	          onClick={() => setOverride(Math.max(0, drawerHoleIndex - 1))}
183	          disabled={drawerHoleIndex === 0}
184	          aria-label="Previous hole"
185	          className="w-9 h-9 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 active:bg-gray-200 disabled:opacity-30"
186	        >
187	          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
188	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
189	          </svg>
190	        </button>
191	
192	        <div className="flex items-center gap-2 text-sm text-gray-500 min-w-0">
193	          {dotHex && (
194	            <span
195	              className="w-3 h-3 rounded-full shrink-0"
196	              style={{ backgroundColor: dotHex, border: dotHex === "#f3f4f6" ? "1px solid #9ca3af" : undefined }}
197	            />
198	          )}
199	          <span className="font-bold text-gray-900">Hole {hole.hole_number}</span>
200	          {hole.hole_name && (
201	            <span className="text-gray-400 truncate">· {hole.hole_name}</span>
202	          )}
203	          <span className="w-px h-4 bg-gray-200 shrink-0" />
204	          <span className="shrink-0">Par <span className="font-bold text-gray-900">{hole.par}</span></span>
205	          <span className="w-px h-4 bg-gray-200 shrink-0" />
206	          <span className="shrink-0"><span className="font-bold text-gray-900">{hole.yards}</span> yds</span>
207	        </div>
208	
209	        <button
210	          type="button"
211	          onClick={() => setOverride(Math.min(holes.length - 1, drawerHoleIndex + 1))}
212	          disabled={drawerHoleIndex === holes.length - 1}
213	          aria-label="Next hole"
214	          className="w-9 h-9 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 active:bg-gray-200 disabled:opacity-30"
215	        >
216	          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
217	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
218	          </svg>
219	        </button>
220	      </div>
221	
222	      {/* Imagery area */}
223	      <div className="flex-1 min-h-0 relative bg-white">
224	        {hasMap && (
225	          <div
226	            className={`absolute inset-0 ${activeView === "map" ? "" : "opacity-0 pointer-events-none"}`}
227	          >
228	            <HoleMapViewLazy
229	              teeLatLng={[hole.tee_latitude!, hole.tee_longitude!]}
230	              greenLatLng={
231	                hole.green_latitude != null && hole.green_longitude != null
232	                  ? [hole.green_latitude, hole.green_longitude]
233	                  : null
234	              }
235	              driveLatLng={
