    () => [
      ...(hasMap ? [{ key: "map" as const, label: "Map" }] : []),
      ...(hasOverhead ? [{ key: "overhead" as const, label: "Overhead" }] : []),
      ...(hasGreen ? [{ key: "green" as const, label: "Green" }] : []),
    ],
    [hasMap, hasOverhead, hasGreen],
  );
