                  onClick={() => setImageView(v.key)}
                  className={`px-3 py-1 text-xs font-medium rounded-md transition-colors ${activeView === v.key ? "bg-white text-gray-900 shadow-sm" : "text-white/80 active:bg-white/10"}`}
