"use client";

import styles from "./score.module.css";
import { computeSkins } from "@/lib/v2/rounds/skins";
import { computeNassau } from "@/lib/v2/rounds/nassau";

const firstName = (name: string) => name.trim().split(/\s+/)[0] || name;

export interface RoundGame {
  id: string;
  game_type: string;
  is_net: boolean;
  participant_ids: string[];
}

/**
 * Live side-game standings on the scorer (#183). Derived from the current scores,
 * so it re-computes on every entry. Skins for now; more games later.
 */
export default function SideGameStandings({
  games,
  playerNames,
  holeNumbers,
  gross,
  strokesByPlayer = {},
}: {
  games: RoundGame[];
  playerNames: Record<string, string>;
  holeNumbers: number[];
  gross: Record<string, Record<number, number>>;
  strokesByPlayer?: Record<string, Record<number, number>>;
}) {
  const skins = games.filter((g) => g.game_type === "skins");
  const nassau = games.filter((g) => g.game_type === "nassau");
  if (skins.length === 0 && nassau.length === 0) return null;

  // Net: subtract each player's per-hole handicap strokes before scoring.
  const netScores = (): Record<string, Record<number, number>> => {
    const out: Record<string, Record<number, number>> = {};
    for (const pid in gross) {
      const m: Record<number, number> = {};
      for (const h in gross[pid]) {
        const strokes = strokesByPlayer[pid]?.[Number(h)] ?? 0;
        m[Number(h)] = gross[pid][Number(h)] - strokes;
      }
      out[pid] = m;
    }
    return out;
  };

  return (
    <div className={styles.sideGames}>
      {skins.map((g) => {
        const scores = g.is_net ? netScores() : gross;
        const r = computeSkins(holeNumbers, scores, g.participant_ids);
        const standings = g.participant_ids
          .map((id) => ({ id, name: playerNames[id] || "Player", won: r.wonBy[id] ?? 0 }))
          .sort((a, b) => b.won - a.won);
        return (
          <div key={g.id} className={styles.sideGame}>
            <div className={styles.sideGameHead}>
              <span className={styles.sideGameTitle}>Skins{g.is_net ? " (Net)" : ""}</span>
              {r.carrying > 0 && <span className={styles.sideGameCarry}>{r.carrying} carrying</span>}
              <span className={styles.sideGameThru}>{r.resolved > 0 ? `thru ${r.resolved}` : "not started"}</span>
            </div>
            <div className={styles.sideGameRows}>
              {standings.map((s) => (
                <div key={s.id} className={styles.sideGameRow}>
                  <span className={styles.sideGameName}>{s.name}</span>
                  <span className={styles.sideGameWon}>{s.won}</span>
                </div>
              ))}
            </div>
          </div>
        );
      })}

      {nassau.map((g) => {
        const [a, b] = g.participant_ids;
        if (!a || !b) {
          return (
            <div key={g.id} className={styles.sideGame}>
              <div className={styles.sideGameHead}>
                <span className={styles.sideGameTitle}>Nassau{g.is_net ? " (Net)" : ""}</span>
              </div>
              <div className={styles.sideGameRows}>
                <span className={styles.sideGameName}>Needs two players.</span>
              </div>
            </div>
          );
        }
        const scores = g.is_net ? netScores() : gross;
        const r = computeNassau(holeNumbers, scores, a, b);
        return (
          <div key={g.id} className={styles.sideGame}>
            <div className={styles.sideGameHead}>
              <span className={styles.sideGameTitle}>Nassau{g.is_net ? " (Net)" : ""}</span>
              <span className={styles.sideGameThru}>
                {firstName(playerNames[a] || "A")} v {firstName(playerNames[b] || "B")}
              </span>
            </div>
            <div className={styles.sideGameRows}>
              {r.segments.map((s) => (
                <div key={s.key} className={styles.sideGameRow}>
                  <span className={styles.sideGameName}>{s.label}</span>
                  <span className={styles.sideGameWon}>
                    {s.leader ? `${firstName(playerNames[s.leader] || "")} ${s.up}↑` : "AS"}
                  </span>
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Nassau (#183): three head-to-head match-play bets in one round — Front 9,
 * Back 9, and Total. Each segment counts holes won: low score wins the hole, ties
 * halve. "Up" is the leader's margin over the segment's scored holes. Two players.
 * Pure — derived from per-hole scores (gross or net).
 */

export interface NassauSegment {
  key: "front" | "back" | "total";
  label: string;
  up: number; // magnitude of the lead (0 = all square)
  leader: string | null; // round_player_id ahead, or null when square
}
export interface NassauResult {
  segments: NassauSegment[];
}

export function computeNassau(
  holeNumbers: number[],
  scores: Record<string, Record<number, number>>,
  a: string,
  b: string,
): NassauResult {
  const front = holeNumbers.filter((h) => h <= 9);
  const back = holeNumbers.filter((h) => h >= 10);
  const hasBoth = front.length > 0 && back.length > 0;

  const segFor = (key: NassauSegment["key"], label: string, holes: number[]): NassauSegment => {
    let diff = 0; // + = a ahead
    for (const h of holes) {
      const sa = scores[a]?.[h];
      const sb = scores[b]?.[h];
      if (sa == null || sb == null) continue;
      if (sa < sb) diff += 1;
      else if (sb < sa) diff -= 1;
    }
    return { key, label, up: Math.abs(diff), leader: diff === 0 ? null : diff > 0 ? a : b };
  };

  // 18-hole: Front, Back, Total. Single nine: just the one match (labelled Total).
  const segments = hasBoth
    ? [segFor("front", "Front 9", front), segFor("back", "Back 9", back), segFor("total", "Total", holeNumbers)]
    : [segFor("total", "Total", holeNumbers)];

  return { segments };
}

