    const ch = calculateCourseHandicap(Number(hi), tee.slope_rating, Number(tee.course_rating), tee.par ?? 72);
    const m: Record<number, number> = {};
    for (const h of holes) m[h.hole_number] = strokesReceivedOnHole(h.handicap_index, ch);
    strokesByPlayer[r.id] = m;
  }
}

