/* Gear button on each game card. */
.sideGameGear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  margin-left: 4px;
  border: none;
  background: transparent;
  color: var(--ink-soft);
  cursor: pointer;
  border-radius: 8px;
}
.sideGameGear:hover {
  background: color-mix(in srgb, var(--ink) 6%, transparent);
  color: var(--ink);
}

/* Pops (handicap strokes) on the scorecard for the current hole. */
.playerNameRow {
  display: flex;
  align-items: center;
  gap: 6px;
}
.pops {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}
.pop {
  width: 4px;
  height: 4px;
  border-radius: 999px;
  background: var(--brand);
}

/* Game settings modal. */
.gsOverlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  padding: 0;
}
.gsModal {
  width: 100%;
  max-width: 460px;
  background: var(--card);
  border-radius: 16px 16px 0 0;
  padding: 16px 16px calc(18px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 88vh;
  overflow-y: auto;
}
@media (min-width: 500px) {
  .gsOverlay { align-items: center; padding: 16px; }
  .gsModal { border-radius: 16px; }
}
.gsHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2px;
}
.gsTitle {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ink);
}
.gsClose {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: none;
  background: transparent;
  color: var(--ink-soft);
  cursor: pointer;
  border-radius: 8px;
}
.gsClose:hover { background: color-mix(in srgb, var(--ink) 6%, transparent); }
.gsLabel {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--ink);
  margin-top: 8px;
}
.gsOptional {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--ink-soft);
