file.content:
  flex: none;
}
.cardTable {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.625rem;
  table-layout: fixed;
}
.cardTable th,
.cardTable td {
  padding: 3px 0;
  text-align: center;
}
.cardHoleBtn {
  width: 100%;
  border: none;
  background: none;
  cursor: pointer;
  font-weight: 700;
  font-size: 0.625rem;
  color: var(--ink-soft);
  padding: 3px 0;
}
.cardHoleBtn[data-active="true"] {
  background: var(--brand);
  color: #fff;
  border-radius: 6px;
}
.cardParRow td,
.cardHcpRow td {
  color: var(--ink-soft);
  font-weight: 600;
}
.cardHcpRow td {
  color: rgba(89, 99, 91, 0.6);
  font-weight: 500;
}
.cardLead {
  color: rgba(89, 99, 91, 0.6);
  font-weight: 700;
  border-right: 1px solid var(--line);
  width: 26px;
}
.cardTot {
  border-left: 1px solid var(--line);
  color: var(--ink-soft);
  font-weight: 700;
}
.cardInitial {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  font-size: 0.6rem;
  font-weight: 700;
}
.cardTotVal {
  border-left: 1px solid var(--line);
  font-weight: 700;
  color: var(--ink);
}

/* Score mark (birdie circle, bogey square, etc.). */
.mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 17px;
  height: 17px;
  font-size: 0.66rem;
  font-weight: 700;
  color: var(--ink);
}
/* Flexbox centers the line box, not the glyph — nudge the digit down so it sits
   optically centered inside the birdie/bogey shapes. */
.markNum {
  display: block;
  transform: translateY(0.5px);
}
/* Scorecard stays monochrome — shape conveys birdie/bogey, not color. */
.mark[data-mark="eagle"],
.mark[data-mark="birdie"] {
  border-radius: 999px;
  border: 1.3px solid var(--ink);
  color: var(--ink);
}
.mark[data-mark="eagle"] {
  box-shadow: 0 0 0 2px var(--card), 0 0 0 3.2px var(--ink);
}
.mark[data-mark="bogey"],
.mark[data-mark="double"] {
  border-radius: 3px;
  border: 1.3px solid var(--ink);
  color: var(--ink);
}
.mark[data-mark="double"] {
  box-shadow: 0 0 0 2px var(--card), 0 0 0 3.2px var(--ink);
}

/* Course strip + save banner. */
.courseStrip {
  position: relative;
  flex: none;

